static std::string QQS_ToLowerCopy(std::string value)
{
	std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
	return value;
}

static const MapChallengeOpenMainMap* FindMapChallengeConfig(UINT MapID)
{
	if (mapChallengeOpenMain.size() == 1)
	{
		for (const auto& map : mapChallengeOpenMain[0].Maps)
		{
			if (map.Mapid == MapID) return &map;
		}
	}
	for (const auto& map : mapChallengeCreate)
	{
		if (map.Mapid == MapID) return &map;
	}
	return nullptr;
}

static UINT MapChallengeAssessMetricValue(const RaceDetailRecord& detail, const MapChallengeAssessConfig& assess)
{
	const std::string type = QQS_ToLowerCopy(assess.type);
	if (type == "cw_jet") return detail.WCJetCount;
	if (type == "wcw_jet") return detail.WCWJetCount;
	if (type == "cww_jet") return detail.CWWJetCount1 ? detail.CWWJetCount1 : detail.CWWJetCount;
	if (type == "small_jet") return detail.SmallJetCount;
	if (type == "drift") return detail.DriftCount;
	if (type == "n2o_gather") return detail.N2OGatherCount;
	if (type == "collision_max") return detail.CollisionCount;
	if (type == "highest_speed_min") return detail.HighestSpeed;
	if (type == "finish") return 1;
	return 0;
}

static bool IsMapChallengeAssessDone(const RaceDetailRecord& detail, const MapChallengeAssessConfig& assess, UINT finishTime)
{
	if (finishTime == 0 || finishTime == 0xFFFFFFFF) return false;
	const std::string type = QQS_ToLowerCopy(assess.type);
	const UINT value = MapChallengeAssessMetricValue(detail, assess);
	if (type == "collision_max") return value <= assess.count;
	if (type == "finish") return true;
	return value >= assess.count;
}

static BYTE MapChallengeDoneStatus(bool oldDone, bool nowDone)
{
	if (nowDone) return oldDone ? 1 : 2;
	return oldDone ? 1 : 0;
}

static void WriteMapChallengeFeedbackInfo(BYTE*& p, const MapChallengeOpenMainMap& mapCfg, BYTE star1Status, BYTE star2Status, BYTE star3Status, BYTE assessStatus)
{
	BYTE* pMapChallengeInfo = p;
	Write16(pMapChallengeInfo, 0); // len
	Write8(pMapChallengeInfo, 3);  // StarInfoNum

	const DWORD starTimes[3] = { mapCfg.firsttime, mapCfg.secondtime, mapCfg.thirdtime };
	const BYTE starStatus[3] = { star1Status, star2Status, star3Status };
	for (int i = 0; i < 3; ++i)
	{
		BYTE* pStar = pMapChallengeInfo;
		Write16(pStar, 0);
		Write32(pStar, starTimes[i]);
		Write8(pStar, starStatus[i]);
		size_t len = pStar - pMapChallengeInfo;
		Set16(pMapChallengeInfo, static_cast<WORD>(len));
		pMapChallengeInfo += len;
	}

	{
		BYTE* pAssessInfo = pMapChallengeInfo;
		Write16(pAssessInfo, 0);
		{
			BYTE* pAssessCfg = pAssessInfo;
			Write16(pAssessCfg, 0);
			Write8(pAssessCfg, static_cast<BYTE>(mapCfg.assess.assessType));
			Write16(pAssessCfg, static_cast<USHORT>(mapCfg.assess.count));
			size_t len = pAssessCfg - pAssessInfo;
			Set16(pAssessInfo, static_cast<WORD>(len));
			pAssessInfo += len;
		}
		Write8(pAssessInfo, assessStatus);
		std::string msg = mapCfg.assess.msg.empty() ? mapCfg.msg : mapCfg.assess.msg;
		try
		{
			msg = UTF2GB(msg.c_str());
		}
		catch (...)
		{
		}
		const size_t msgLen = std::min<size_t>(msg.size(), 65535);
		Write16(pAssessInfo, static_cast<WORD>(msgLen));
		if (msgLen > 0)
		{
			memcpy(pAssessInfo, msg.data(), msgLen);
			pAssessInfo += msgLen;
		}
		size_t len = pAssessInfo - pMapChallengeInfo;
		Set16(pMapChallengeInfo, static_cast<WORD>(len));
		pMapChallengeInfo += len;
	}

	Write32(pMapChallengeInfo, mapCfg.Mapid);
	size_t len = pMapChallengeInfo - p;
	Set16(p, static_cast<WORD>(len));
	p = pMapChallengeInfo;
}

static void NotifyMapChallengeFeedBackData935(std::shared_ptr<ClientNode> Client, const MapChallengeOpenMainMap& mapCfg, BYTE star1Status, BYTE star2Status, BYTE star3Status, BYTE assessStatus)
{
	if (!Client) return;
	std::vector<BYTE> buf(8192);
	BYTE* p = buf.data();

	{
		BYTE* pFeedBack = p;
		Write16(pFeedBack, 0);
		Write32(pFeedBack, Client->ranknumber);
		Write8(pFeedBack, 0);
		{
			BYTE* pCurRecord = pFeedBack;
			Write16(pCurRecord, 0);
			Write32(pCurRecord, Client->MapID);
			Write32(pCurRecord, Client->FinishTime);
			Write32(pCurRecord, Client->RaceDetail.HighestSpeed ? Client->RaceDetail.HighestSpeed : Client->HighestSpeed);
			Write32(pCurRecord, Client->RaceDetail.DriftCount ? Client->RaceDetail.DriftCount : Client->DriftCount);
			Write32(pCurRecord, Client->RaceDetail.N2OGatherCount ? Client->RaceDetail.N2OGatherCount : Client->N2OGatherCount);
			Write32(pCurRecord, Client->RaceDetail.CollisionCount ? Client->RaceDetail.CollisionCount : Client->CollisionCount);
			size_t len = pCurRecord - pFeedBack;
			Set16(pFeedBack, static_cast<WORD>(len));
			pFeedBack += len;
		}
		{
			BYTE* pBestRecord = pFeedBack;
			Write16(pBestRecord, 0);
			const DWORD bestTime = PlayerDB_GetMapRecord(Client->Uin, Client->MapID, Client);
			Write32(pBestRecord, Client->MapID);
			Write32(pBestRecord, bestTime);
			Write32(pBestRecord, Client->RaceDetail.HighestSpeed ? Client->RaceDetail.HighestSpeed : Client->HighestSpeed);
			Write32(pBestRecord, Client->RaceDetail.DriftCount ? Client->RaceDetail.DriftCount : Client->DriftCount);
			Write32(pBestRecord, Client->RaceDetail.N2OGatherCount ? Client->RaceDetail.N2OGatherCount : Client->N2OGatherCount);
			Write32(pBestRecord, Client->RaceDetail.CollisionCount ? Client->RaceDetail.CollisionCount : Client->CollisionCount);
			size_t len = pBestRecord - pFeedBack;
			Set16(pFeedBack, static_cast<WORD>(len));
			pFeedBack += len;
		}
		Write32(pFeedBack, 0); // GameEvaluation
		Write32(pFeedBack, 0); // PlayerEvaluation
		Write32(pFeedBack, 0); // KartEvaluation
		Write32(pFeedBack, 0); // RefitTryOutIncTime
		Write8(pFeedBack, 0);  // WeightNum
		Write32(pFeedBack, Client->Uin);
		Write32(pFeedBack, Client->ranknumber);
		Write8(pFeedBack, 0); // HaveGameLogicTask
		size_t len = pFeedBack - p;
		Set16(p, static_cast<WORD>(len));
		p += len;
	}

	Write8(p, 1); // MapChallengeInfoNum
	WriteMapChallengeFeedbackInfo(p, mapCfg, star1Status, star2Status, star3Status, assessStatus);

	const DWORD len = static_cast<DWORD>(p - buf.data());
	SendToClient(Client, 935, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
	QQS_DebugPrintf10001("[MAPCHALLENGE-935] Uin=%u MapID=%u Finish=%u StarStatus=%u/%u/%u AssessStatus=%u WCW=%u Len=%u\n",
		Client->Uin, Client->MapID, Client->FinishTime, star1Status, star2Status, star3Status, assessStatus, Client->RaceDetail.WCWJetCount, len);
}

static bool SpeedLadder_IsOfficialTrophyRaceRoom(const std::shared_ptr<RoomNode>& RaceRoom)
{
	if (!RaceRoom)
		return false;
	if (RaceRoom->HasCustomScheme || RaceRoom->SpeFlag == 9)
		return false;
	if (IsTwelvePlayerRoom(RaceRoom) || GetRoomSeatLimit(RaceRoom) > ROOM_SEAT_NORMAL_MAX)
		return false;
	return RaceRoom->BaseGameMode == 1 && RaceRoom->SubGameMode == 1;
}

static const char* SpeedLadder_GetTrophyRaceSource(const std::shared_ptr<RoomNode>& RaceRoom, bool SpeedLadderUiContext, const char* CallerSource)
{
	if (SpeedLadderUiContext)
		return "speedladder-ui";
	if (IsBorderTeamMatchRoom(RaceRoom))
		return "border-room";
	if (CallerSource && CallerSource[0])
		return CallerSource;
	return "normal-room";
}

static void HandleRaceChallengeFinish(std::shared_ptr<ClientNode> Client, const std::shared_ptr<RoomNode>& RaceRoom, const char* CallerSource)
{
	if (!Client || Client->Uin == 0 || Client->MapID == 0 || Client->FinishTime == 0 || Client->FinishTime == 0xFFFFFFFF)
	{
		if (Client && Client->SpeedLadderRaceActive)
			SpeedLadder_ClearRaceContext(Client, "finish-invalid");
		return;
	}

	const MapChallengeOpenMainMap* mapCfg = FindMapChallengeConfig(Client->MapID);
	BYTE trophyLevel = 0;
	BYTE trophyCount = 0;
	const bool speedLadderMap = SpeedLadder_CalcTrophyForMap(Client->MapID, Client->FinishTime, trophyLevel, trophyCount);
	if (!mapCfg && !speedLadderMap)
	{
		if (Client->SpeedLadderRaceActive)
			SpeedLadder_ClearRaceContext(Client, "finish-map-not-configured");
		return;
	}

	const UINT seasonID = SpeedLadder_GetCurrentSeasonID();
	const DWORD finishTime = static_cast<DWORD>(Client->FinishTime);
	const bool speedLadderUiContext =
		speedLadderMap &&
		Client->SpeedLadderRaceActive &&
		(Client->SpeedLadderRaceMapID == 0 || Client->SpeedLadderRaceMapID == Client->MapID) &&
		(Client->SpeedLadderRaceSeasonID == 0 || Client->SpeedLadderRaceSeasonID == seasonID);
	const bool speedLadderRoomContext = speedLadderMap && SpeedLadder_IsOfficialTrophyRaceRoom(RaceRoom);
	const bool speedLadderRaceContext = speedLadderUiContext || speedLadderRoomContext;
	const char* speedLadderRaceSource = SpeedLadder_GetTrophyRaceSource(RaceRoom, speedLadderUiContext, CallerSource);

	char replayPath[128] = { 0 };
	snprintf(replayPath, sizeof(replayPath), "local-%u-%u-%u", Client->Uin, Client->MapID, static_cast<UINT>(time(nullptr)));
	const std::string replayMd5 = "00000000000000000000000000000000";

	if (speedLadderRaceContext)
	{
		SpeedLadderPlayerMapRow oldRow;
		const bool hasOldRow = PlayerDB_GetSpeedLadderPlayerMapBySource(Client->Uin, seasonID, Client->MapID, SPEED_LADDER_RECORD_SOURCE_SPEED_LADDER, oldRow);
		const bool hadOldLadder =
			hasOldRow &&
			oldRow.RecordSource == SPEED_LADDER_RECORD_SOURCE_SPEED_LADDER &&
			oldRow.BestTime != 0 &&
			oldRow.BestTime != 0xFFFFFFFF;
		const DWORD oldTime = hadOldLadder ? oldRow.BestTime : 0xFFFFFFFF;
		const BYTE oldTrophyLevel = hadOldLadder ? oldRow.TrophyLevel : 0;
		const BYTE oldTrophyCount = hadOldLadder ? oldRow.TrophyCount : 0;
		const bool ladderBestUpdated = PlayerDB_UpsertSpeedLadderPlayerMap(
			Client->Uin, seasonID, Client->MapID, finishTime, trophyLevel, trophyCount,
			0, 0, 0, 0, SPEED_LADDER_RECORD_SOURCE_SPEED_LADDER, replayMd5, replayPath);
		const bool firstComplete = !hadOldLadder;
		const bool trophyIncreased = trophyCount > oldTrophyCount;
		const BYTE deltaTrophyCount = trophyIncreased ? static_cast<BYTE>(trophyCount - oldTrophyCount) : 0;
		const bool shouldNotify = firstComplete || ladderBestUpdated || trophyIncreased;
		if (shouldNotify)
		{
			NotifySpeedLadderBreakMapRecordQuickRPC(
				Client,
				Client->MapID,
				oldTime,
				oldTrophyLevel,
				finishTime,
				trophyLevel,
				trophyCount,
				trophyIncreased,
				firstComplete);
		}
		QQS_DebugPrintf10001("[SPEEDLADDER-SETTLE] Source=%s Uin=%u Season=%u MapID=%u OldLevel=%u NewLevel=%u OldCount=%u NewCount=%u DeltaCount=%u Crossed=%u First=%u Notify=%u UiCtx=%u RoomCtx=%u RoomID=%u Border=%u Custom=%u SpeFlag=%u Is12=%u\n",
			speedLadderRaceSource, Client->Uin, seasonID, Client->MapID, oldTrophyLevel, trophyLevel, oldTrophyCount, trophyCount,
			deltaTrophyCount, trophyIncreased ? 1 : 0, firstComplete ? 1 : 0, shouldNotify ? 1 : 0,
			speedLadderUiContext ? 1 : 0, speedLadderRoomContext ? 1 : 0,
			RaceRoom ? RaceRoom->ID : 0, IsBorderTeamMatchRoom(RaceRoom) ? 1 : 0,
			(RaceRoom && RaceRoom->HasCustomScheme) ? 1 : 0, RaceRoom ? (unsigned)RaceRoom->SpeFlag : 0,
			IsTwelvePlayerRoom(RaceRoom) ? 1 : 0);
		QQS_DebugPrintf10001("[SPEEDLADDER-RECORD] Source=%s Uin=%u Season=%u MapID=%u BestTime=%u SourceID=%u Updated=%u First=%u OldTime=%u OldLevel=%u NewLevel=%u OldCount=%u NewCount=%u Notify=%u\n",
			speedLadderRaceSource, Client->Uin, seasonID, Client->MapID, finishTime, SPEED_LADDER_RECORD_SOURCE_SPEED_LADDER,
			ladderBestUpdated ? 1 : 0, firstComplete ? 1 : 0, oldTime, oldTrophyLevel, trophyLevel, oldTrophyCount, trophyCount, shouldNotify ? 1 : 0);
		if (speedLadderUiContext)
			SpeedLadder_MarkReturnContext(Client, Client->MapID, seasonID, "finish-speed-ladder-ui");
		if (Client->SpeedLadderRacePending || Client->SpeedLadderRaceActive)
			SpeedLadder_ClearRaceContext(Client, speedLadderUiContext ? "finish-speed-ladder-ui" : "finish-speed-ladder-room");
		return;
	}

	if (mapCfg)
	{
		SpeedLadderPlayerMapRow oldRow;
		const bool hasOldRow = PlayerDB_GetSpeedLadderPlayerMapBySource(Client->Uin, seasonID, Client->MapID, SPEED_LADDER_RECORD_SOURCE_MAP_CHALLENGE, oldRow);
		const bool star1Done = finishTime <= mapCfg->firsttime;
		const bool star2Done = finishTime <= mapCfg->secondtime;
		const bool star3Done = finishTime <= mapCfg->thirdtime;
		const bool assessDone = IsMapChallengeAssessDone(Client->RaceDetail, mapCfg->assess, finishTime);
		const bool challengeBestUpdated = PlayerDB_UpsertSpeedLadderPlayerMap(
			Client->Uin, seasonID, Client->MapID, finishTime, trophyLevel, trophyCount,
			star1Done ? 1 : 0, star2Done ? 1 : 0, star3Done ? 1 : 0, assessDone ? 1 : 0,
			SPEED_LADDER_RECORD_SOURCE_MAP_CHALLENGE, replayMd5, replayPath);
		const BYTE star1Status = MapChallengeDoneStatus(hasOldRow && oldRow.Star1Done != 0, star1Done);
		const BYTE star2Status = MapChallengeDoneStatus(hasOldRow && oldRow.Star2Done != 0, star2Done);
		const BYTE star3Status = MapChallengeDoneStatus(hasOldRow && oldRow.Star3Done != 0, star3Done);
		const BYTE assessStatus = MapChallengeDoneStatus(hasOldRow && oldRow.AssessDone != 0, assessDone);
		NotifyMapChallengeFeedBackData935(Client, *mapCfg, star1Status, star2Status, star3Status, assessStatus);
		QQS_DebugPrintf10001("[MAPCHALLENGE-RECORD] Uin=%u Season=%u MapID=%u BestTime=%u Source=%u Updated=%u TrophyLevel=%u TrophyCount=%u\n",
			Client->Uin, seasonID, Client->MapID, finishTime, SPEED_LADDER_RECORD_SOURCE_MAP_CHALLENGE, challengeBestUpdated ? 1 : 0, trophyLevel, trophyCount);
		if (!speedLadderMap)
		{
			QQS_DebugPrintf10001("[SPEEDLADDER-SKIP] Uin=%u MapID=%u Finish=%u not in SpeedLadderMaps.yml\n",
				Client->Uin, Client->MapID, finishTime);
		}
	}
	else if (speedLadderMap)
	{
		QQS_DebugPrintf10001("[SPEEDLADDER-SKIP] Uin=%u Season=%u MapID=%u Finish=%u TrophyLevel=%u TrophyCount=%u no eligible speed-ladder trophy race context Pending=%u Active=%u RaceMap=%u RaceSeason=%u RoomOK=%u Caller=%s RoomID=%u Base=%u Sub=%u Border=%u Custom=%u SpeFlag=%u Is12=%u\n",
			Client->Uin, seasonID, Client->MapID, finishTime, trophyLevel, trophyCount,
			Client->SpeedLadderRacePending ? 1 : 0, Client->SpeedLadderRaceActive ? 1 : 0,
			Client->SpeedLadderRaceMapID, Client->SpeedLadderRaceSeasonID,
			SpeedLadder_IsOfficialTrophyRaceRoom(RaceRoom) ? 1 : 0,
			CallerSource ? CallerSource : "",
			RaceRoom ? RaceRoom->ID : 0, RaceRoom ? (unsigned)RaceRoom->BaseGameMode : 0, RaceRoom ? (unsigned)RaceRoom->SubGameMode : 0,
			IsBorderTeamMatchRoom(RaceRoom) ? 1 : 0, (RaceRoom && RaceRoom->HasCustomScheme) ? 1 : 0,
			RaceRoom ? (unsigned)RaceRoom->SpeFlag : 0, IsTwelvePlayerRoom(RaceRoom) ? 1 : 0);
		if (Client->SpeedLadderRaceActive)
			SpeedLadder_ClearRaceContext(Client, "finish-speed-ladder-mismatch");
	}
	else if (Client->SpeedLadderRaceActive)
	{
		SpeedLadder_ClearRaceContext(Client, "finish-not-speed-ladder-map");
	}
}

static bool LoadRaceKartStoneInfo(UINT Uin, UINT KartID, std::vector<KartStoneItemInfo>& stones)
{
	stones.clear();
	if (Uin == 0 || KartID == 0)
		return false;

	PlayerDB_SelectKartStone(Uin, KartID, stones);
	stones.erase(std::remove_if(stones.begin(), stones.end(), [](const KartStoneItemInfo& info) {
		return info.SkillStoneID == 0;
		}), stones.end());
	for (auto& info : stones)
		info.KartId = KartID;
	return !stones.empty();
}

static UINT GetVisibleKartForStone(const std::shared_ptr<ClientNode>& Player)
{
	if (!Player)
		return 0;
	return Player->KartSkinID ? Player->KartSkinID : Player->KartID;
}

static bool LoadRaceKartStoneInfoForVisibleKart(const std::shared_ptr<ClientNode>& Player, std::vector<KartStoneItemInfo>& stones, UINT& sourceKartID, UINT& packetKartID)
{
	stones.clear();
	sourceKartID = 0;
	packetKartID = GetVisibleKartForStone(Player);
	if (!Player || Player->Uin == 0 || packetKartID == 0)
		return false;

	// Client applies SyncCar stone info by the visible CurCarID.  When a skin is
	// equipped the DB often stores grooves on the base kart, so load from base as
	// fallback but still write packet KartID as the visible skin.
	if (LoadRaceKartStoneInfo(Player->Uin, packetKartID, stones))
	{
		sourceKartID = packetKartID;
		return true;
	}
	if (Player->KartID != 0 && Player->KartID != packetKartID && LoadRaceKartStoneInfo(Player->Uin, Player->KartID, stones))
	{
		sourceKartID = Player->KartID;
		return true;
	}
	return false;
}

static bool HasValidRankedStonePresetConfig()
{
	if (!MSingleSkillStoneCfg || MSingleSkillStoneCfg->RankedStonePresetIDs.empty() ||
		MSingleSkillStoneCfg->RankedStonePresetIDs.size() > 5)
	{
		return false;
	}

	for (UINT stoneID : MSingleSkillStoneCfg->RankedStonePresetIDs)
	{
		if (stoneID == 0)
			return false;
		const auto it = std::find_if(
			MSingleSkillStoneCfg->SkillStoneCfg.begin(),
			MSingleSkillStoneCfg->SkillStoneCfg.end(),
			[stoneID](const SKILLSTONECFG& config) { return config.StoneID == stoneID; });
		if (it == MSingleSkillStoneCfg->SkillStoneCfg.end())
			return false;
	}
	return true;
}

bool IsRankedStonePresetEnabled()
{
	return rankstone != 0;
}

bool IsConfiguredRankedStonePresetID(UINT StoneID)
{
	if (!IsRankedStonePresetEnabled() || !HasValidRankedStonePresetConfig())
		return false;
	return std::find(
		MSingleSkillStoneCfg->RankedStonePresetIDs.begin(),
		MSingleSkillStoneCfg->RankedStonePresetIDs.end(),
		StoneID) != MSingleSkillStoneCfg->RankedStonePresetIDs.end();
}

static bool IsRankedStonePresetContext(const std::shared_ptr<ClientNode>& Player)
{
	if (!Player || !IsRankedStonePresetEnabled())
		return false;
	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(Player);
	return room && room->matchQueueType == 0x0A && Player->TaskID == 0xFFFC &&
		room->RaceGameID != 0 && Player->GameID == room->RaceGameID;
}

static bool LoadRankedStonePresetForPlayer(
	const std::shared_ptr<ClientNode>& Player,
	std::vector<KartStoneItemInfo>& stones,
	UINT& sourceKartID,
	UINT& packetKartID)
{
	stones.clear();
	sourceKartID = 0;
	packetKartID = GetVisibleKartForStone(Player);
	if (!Player || packetKartID == 0 || !HasValidRankedStonePresetConfig())
		return false;

	sourceKartID = packetKartID;
	for (UINT stoneID : MSingleSkillStoneCfg->RankedStonePresetIDs)
	{
		KartStoneItemInfo info{};
		info.KartId = packetKartID;
		info.StoneUseOccaType = 0;
		info.SkillStoneID = stoneID;
		stones.push_back(info);
	}
	return true;
}

static bool LoadEffectiveRaceKartStoneInfo(
	const std::shared_ptr<ClientNode>& Player,
	std::vector<KartStoneItemInfo>& stones,
	UINT& sourceKartID,
	UINT& packetKartID)
{
	if (IsRankedStonePresetContext(Player))
		return LoadRankedStonePresetForPlayer(Player, stones, sourceKartID, packetKartID);

	LoadRaceKartStoneInfoForVisibleKart(Player, stones, sourceKartID, packetKartID);
	if (stones.empty() && Player && Player->GlobalStone == 1)
	{
		const auto item = std::find_if(itemSkillStone.begin(), itemSkillStone.end(), [Player](const ItemSkillStone& entry) {
			return entry.ItemID == Player->GlobalItemStoneid;
			});
		if (item != itemSkillStone.end())
		{
			sourceKartID = Player->GlobalItemStoneid;
			packetKartID = GetVisibleKartForStone(Player);
			for (size_t i = 0; i < item->StoneCfg.size() && i < 5; ++i)
			{
				KartStoneItemInfo info{};
				info.KartId = packetKartID;
				info.StoneUseOccaType = 0;
				info.SkillStoneID = item->StoneCfg[i].StoneID;
				stones.push_back(info);
			}
		}
	}
	if (stones.size() > 5)
		stones.resize(5);
	return !stones.empty();
}

static const SKILLSTONECFG* FindSkillStoneConfig(UINT stoneID)
{
	if (!MSingleSkillStoneCfg)
		return nullptr;
	const auto it = std::find_if(
		MSingleSkillStoneCfg->SkillStoneCfg.begin(),
		MSingleSkillStoneCfg->SkillStoneCfg.end(),
		[stoneID](const SKILLSTONECFG& config) { return config.StoneID == stoneID; });
	return it != MSingleSkillStoneCfg->SkillStoneCfg.end() ? &(*it) : nullptr;
}

static const SKILLSTONESERVERRULE* FindSkillStoneServerRule(UINT stoneID)
{
	if (!MSingleSkillStoneCfg)
		return nullptr;
	for (const auto& rule : MSingleSkillStoneCfg->ServerRules)
	{
		if (std::find(rule.StoneIDs.begin(), rule.StoneIDs.end(), stoneID) != rule.StoneIDs.end())
			return &rule;
	}
	return nullptr;
}

static bool SendRankedStonePreset906(
	const std::shared_ptr<ClientNode>& Client,
	UINT kartID)
{
	if (!IsRankedStonePresetContext(Client) || kartID == 0 ||
		!HasValidRankedStonePresetConfig())
	{
		return false;
	}

	std::vector<BYTE> buf(128);
	BYTE* p = buf.data();
	Write32(p, Client->Uin);
	BYTE* pKartStoneInfo = p;
	Write16(pKartStoneInfo, 0);
	Write32(pKartStoneInfo, kartID);
	Write32(pKartStoneInfo, static_cast<DWORD>(MSingleSkillStoneCfg->RankedStonePresetIDs.size()));
	for (UINT stoneID : MSingleSkillStoneCfg->RankedStonePresetIDs)
	{
		BYTE* pStoneGrooveInfo = pKartStoneInfo;
		Write16(pStoneGrooveInfo, 0);
		Write32(pStoneGrooveInfo, 0); // StoneUseOccaType
		Write32(pStoneGrooveInfo, stoneID);
		const size_t stoneInfoLen = static_cast<size_t>(pStoneGrooveInfo - pKartStoneInfo);
		Set16(pKartStoneInfo, static_cast<WORD>(stoneInfoLen));
		pKartStoneInfo += stoneInfoLen;
	}
	const size_t kartInfoLen = static_cast<size_t>(pKartStoneInfo - p);
	Set16(p, static_cast<WORD>(kartInfoLen));
	p += kartInfoLen;

	return SendToClient(
		Client, 906, buf.data(), static_cast<DWORD>(p - buf.data()),
		Client->ConnID, FE_PLAYER, 1, Notify) != FALSE;
}

bool NotifyRankedStonePresetForKartAndSkin(std::shared_ptr<ClientNode> Client)
{
	if (!IsRankedStonePresetEnabled())
		return true;
	if (!Client || !IsRankedStonePresetContext(Client) || Client->KartID == 0 ||
		!HasValidRankedStonePresetConfig())
	{
		return false;
	}

	const bool baseSent = SendRankedStonePreset906(Client, Client->KartID);
	const bool skinSent = Client->KartSkinID == 0 || Client->KartSkinID == Client->KartID
		? true
		: SendRankedStonePreset906(Client, Client->KartSkinID);
	if (baseSent && skinSent)
	{
		Client->ServerSkillStoneGameID = 0;
		Client->ServerSkillStoneID = 0;
		Client->ServerSkillStoneUseCount = 0;
		Client->ServerSkillStoneLastActivationTick = 0;
		Client->ServerSkillStoneHasActivated = false;
	}
	QQS_DebugPrintf10001(
		"[RANKED-STONE][906] Uin=%u KartID=%u SkinID=%u Count=%zu BaseSent=%d SkinSent=%d\n",
		Client->Uin, Client->KartID, Client->KartSkinID,
		MSingleSkillStoneCfg->RankedStonePresetIDs.size(), baseSent ? 1 : 0, skinSent ? 1 : 0);
	return baseSent && skinSent;
}

static void BindServerSkillStoneForCurrentRace(const std::shared_ptr<ClientNode>& Client)
{
	if (!Client)
		return;

	Client->ServerSkillStoneGameID = Client->GameID;
	Client->ServerSkillStoneID = 0;
	Client->ServerSkillStoneUseCount = 0;
	Client->ServerSkillStoneLastActivationTick = 0;
	Client->ServerSkillStoneHasActivated = false;

	std::vector<KartStoneItemInfo> stones;
	UINT sourceKartID = 0;
	UINT packetKartID = 0;
	LoadEffectiveRaceKartStoneInfo(Client, stones, sourceKartID, packetKartID);
	for (const auto& stone : stones)
	{
		if (FindSkillStoneServerRule(stone.SkillStoneID))
		{
			// 同一技能类型只取客户端槽位顺序中的第一颗，与 Msg908 处理端的选择方式一致。
			Client->ServerSkillStoneID = stone.SkillStoneID;
			break;
		}
	}
}

static bool WriteRaceSyncCarStoneInfo(BYTE*& pSyncCar, const std::shared_ptr<ClientNode>& Player, UINT packetKartIDOverride = 0)
{
	if (!Player)
	{
		Write8(pSyncCar, 0); // HasStoneInfo
		return false;
	}

	std::vector<KartStoneItemInfo> stones;
	UINT sourceKartID = 0;
	UINT stoneKartID = GetVisibleKartForStone(Player);
	LoadEffectiveRaceKartStoneInfo(Player, stones, sourceKartID, stoneKartID);
	if (!stones.empty() && Player->GlobalStone == 1 && sourceKartID == Player->GlobalItemStoneid)
	{
		QQS_DebugPrintf10001("[FLOW][509-STONE-GLOBAL] Uin=%u KartID=%u GlobalItemStoneID=%u StoneNum=%zu\n",
			Player->Uin, stoneKartID, Player->GlobalItemStoneid, stones.size());
	}

	if (stones.empty())
	{
		Write8(pSyncCar, 0); // HasStoneInfo
		return false;
	}

	if (stones.size() > 5)
		stones.resize(5);

	UINT packetStoneKartID = packetKartIDOverride ? packetKartIDOverride : stoneKartID;

	Write8(pSyncCar, 1); // HasStoneInfo
	BYTE* pSTKartStoneGrooveInfo = pSyncCar;
	Write16(pSTKartStoneGrooveInfo, 0); // len
	Write32(pSTKartStoneGrooveInfo, packetStoneKartID);
	Write32(pSTKartStoneGrooveInfo, (UINT)stones.size());
	for (size_t i = 0; i < stones.size(); i++)
	{
		BYTE* pStoneGrooveInfo = pSTKartStoneGrooveInfo;
		Write16(pStoneGrooveInfo, 0); // len
		Write32(pStoneGrooveInfo, stones[i].StoneUseOccaType);
		Write32(pStoneGrooveInfo, stones[i].SkillStoneID);
		size_t len = pStoneGrooveInfo - pSTKartStoneGrooveInfo;
		Set16(pSTKartStoneGrooveInfo, (WORD)len);
		pSTKartStoneGrooveInfo += len;
	}
	size_t len = pSTKartStoneGrooveInfo - pSyncCar;
	Set16(pSyncCar, (WORD)len);
	pSyncCar += len;
	QQS_DebugPrintf10001("[FLOW][509-STONE] Uin=%u KartID=%u SkinID=%u PacketStoneKartID=%u SourceKartID=%u StoneNum=%zu Override=%u\n",
		Player->Uin, Player->KartID, Player->KartSkinID, packetStoneKartID, sourceKartID, stones.size(), packetKartIDOverride);
	return true;
}

