static void WriteSimplifiedPinnacleBattleExtraComputeInfo(BYTE*& pRankedMatchComputeInfo, bool Win)
{
	constexpr UINT ENMREGT_PinnacleBattlePlayer = 6; // RankedGameCfg.TopRaceCfg.GameOverViewCfg.ExtraComputeType

	BYTE* pRankedMatchExtracComputeInfos = pRankedMatchComputeInfo;
	Write16(pRankedMatchExtracComputeInfos, 0); // len

	Write32(pRankedMatchExtracComputeInfos, ENMREGT_PinnacleBattlePlayer); // ExtraComputeType
	Write32(pRankedMatchExtracComputeInfos, 1); // AwardItemNums
	Write32(pRankedMatchExtracComputeInfos, 1); // WeekylyAwardItemNums
	Write32(pRankedMatchExtracComputeInfos, 999); // WeeklyAwardItemLimitNums
	Write8(pRankedMatchExtracComputeInfos, 0); // HaveGameLogicTask

	Write8(pRankedMatchExtracComputeInfos, Win ? 1 : 0); // Win
	Write8(pRankedMatchExtracComputeInfos, 0); // NormalPlayerOrNot: 0=special player, triggers SpecialPlayerCfg
	Write8(pRankedMatchExtracComputeInfos, 1); // LeadRolePlayerNums

	size_t len = pRankedMatchExtracComputeInfos - pRankedMatchComputeInfo;
	Set16(pRankedMatchComputeInfo, (WORD)len);
	pRankedMatchComputeInfo += len;
}


