static bool RestoreBorderTeamReturnStateOnly(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room, const char* reason)
{
	if (!Client || !Room || !IsBorderTeamRoomForReturn(Room))
		return false;

	Room->AllowAutoStart = 0;
	Room->startStatus = 1;
	Room->Callback = NULL;
	Room->RaceActiveMask = 0;
	Room->RaceStartPlayerNum = 0;
	Room->CountDownFlag = 0;

	PrepareOfficialRoomReturnParticipant(
		Client, Room,
		QQS_OFFICIAL_ROOM_RETURN_KIND_BORDER_TEAM,
		QQS_OFFICIAL_ROOM_RETURN_PHASE_SERVER_CHAIN_PENDING,
		reason ? reason : "border-team-return-restore-only");
	FinalizeOfficialRoomReturnParticipant(Client, Room);
	Client->TaskID = 0;
	Client->BorderRoomID = 0;

	const int seatLimit = GetRoomSeatLimit(Room);
	EnsureRoomOwnerAlive(Room, Client, reason ? reason : "border-team-return-restore-only");
	Client->LastRoomReturnTick = GetTickCount();
	QQS_DebugPrintf10001("[FLOW][BORDER-RETURN-RESTORE-ONLY] Reason=%s Uin=%u TeamRoomID=%u Seat=%d SeatLimit=%d -> defer 104/500 until whole team restored\n",
		reason ? reason : "", Client->Uin, Room->ID, Client->SeatID, seatLimit);
	return true;
}

static int SendBorderTeamReturnRoomOfficialRoster(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room, const char* reason)
{
	if (!Client || !Room || !IsBorderTeamRoomForReturn(Room))
		return 0;

	if (Client->RoomID != Room->ID || Client->CurrentRoom != Room.get())
		RestoreBorderTeamReturnStateOnly(Client, Room, reason ? reason : "border-team-return-roster-self-fix");

	Room->AllowAutoStart = 0;
	Room->startStatus = 1;
	Room->Callback = NULL;
	Room->RaceActiveMask = 0;
	Room->RaceStartPlayerNum = 0;
	Room->CountDownFlag = 0;

	const int seatLimit = GetRoomSeatLimit(Room);
	NormalizeOfficialReturnRosterLinks(Room, reason ? reason : "border-team-return-roster");

	Client->LastRoomReturnTick = GetTickCount();
	ResponseEnterRoom(Client, Room, Client->SeatID, 0, 0, EnterRoom104RosterMode::Empty);

	int notify500Count = 0;
	const int visiblePlayerCount = CountReturnRoomVisiblePlayers(Room, seatLimit);
	for (char j = 0; j < seatLimit && j < (char)Room->Player.size(); j++)
	{
		std::shared_ptr<ClientNode> RoomClient2 = Room->Player[j];
		if (!RoomClient2)
			continue;
		if (RoomClient2 == Client)
			continue;
		if (RoomClient2->deleteflag || !RoomClient2->IsLogin || RoomClient2->Uin == 0 || RoomClient2->OBState)
			continue;
		if (RoomClient2->RoomID != Room->ID || RoomClient2->CurrentRoom != Room.get())
			continue;
		NotifyEnterRoom(Client, Room, RoomClient2, RoomClient2->SeatID);
		notify500Count++;
	}
	// 104/500 先重建其他玩家对象，再用 504/609 刷新这些已有对象；
	// 接收者自己不在官服 roster 中，其准备状态只由后续 C109 提交。
	NotifyOfficialReturnReadyObRoster(Client, Room, reason ? reason : "border-team-return-ready-reset");
	if (Client->OfficialRoomReturn.Phase == QQS_OFFICIAL_ROOM_RETURN_PHASE_SERVER_CHAIN_PENDING)
	{
		AdvanceOfficialRoomReturnFlow(
			Client, Room,
			QQS_OFFICIAL_ROOM_RETURN_PHASE_SERVER_CHAIN_PENDING,
			QQS_OFFICIAL_ROOM_RETURN_PHASE_WAIT_AT62_ACK_ONLY,
			reason ? reason : "border-team-return-server-chain-complete");
	}

	QQS_DebugPrintf10001("[FLOW][BORDER-RETURN-ROSTER-OFFICIAL] Reason=%s Uin=%u TeamRoomID=%u Notify500=%d ActiveReturnPlayers=%d RosterCountExpected=%d SeatLimit=%d OwnerID=%u SelfWireID=%u -> 105/104/500/504/609 then wait 24640 AT=62, no 24390/524\n",
		reason ? reason : "", Client->Uin, Room->ID, notify500Count,
		visiblePlayerCount, visiblePlayerCount > 0 ? visiblePlayerCount - 1 : 0, seatLimit,
		(unsigned)GetRoomConnOwnerID(Room), (unsigned)GetRoomConnPlayerID(Room, Client));
	return notify500Count;
}

