void AddSuperMoney(std::shared_ptr<ClientNode> Client) {
	if (Client->FinishTime > 0 && RankAdd[0] == 1) {
		SelectClientExp(Client);
		Client->SuperMoney += RankAdd[1];
		UpdateClientBase(Client);
	}
}

struct RankedGradeSnapshot
{
	UINT GradeLevel = 0;
	UINT ChildLevel = 0;
	UINT GradeScore = 0;
	UINT MaxGradeScore = 0;
	UINT TotalScore = 0;
};

struct RankedPromoSnapshot
{
	BYTE PromotionMatch = 0;
	UINT PromotionRoundNums = 0;
	UINT PromotionSuccessRoundNums = 0;
	UINT PromotionAlreadySuccessRoundNums = 0;
	UINT PromotionRecordTag = 0;
	UINT CurrentPromotionRoundNums = 0;
	INT PromoFailedMinusScore = 0;
	INT PromoSuccAddScore = 0;
	BYTE PromoDirectly = 0;
	BYTE GradeNoNeedPromo = 0;
	BYTE RankedMemoryNoNeedPromo = 0;
	BYTE PromotionExtraScore = 0;
	BYTE PromtRaceFailedDefendFlag = 0;
};

struct RankedComputeSnapshot
{
	INT RankAddScore = 0;
	INT FinishAddScore = 0;
	INT KillAllAddScore = 0;
	INT GradeProtectAddScore = 0;
	INT GradeAddScore = 0;
	UINT ProtectAddScoreGradeLimit = 23;
	UINT AwardRankCoinNums = 0;
	UINT AwardRankCoinNumsByRank = 0;
	UINT AwardRankCoinNumsByFinish = 0;
	UINT SeasonRaceNums = 0;
};

struct RankedSettlementEntry
{
	std::shared_ptr<ClientNode> Player;
	UINT Uin = 0;
	UINT FinishTime = 0xFFFFFFFF;
	UINT KartID = 0;
	UINT TotalMoney = 0;
	UINT TotalExp = 0;
	UINT DistanceToEnd = 0;
	BYTE TeamID = 0;
	RankedGradeSnapshot LastGrade;
	RankedGradeSnapshot NewGrade;
	RankedPromoSnapshot Promo;
	RankedComputeSnapshot Compute;
};

struct RankedSettlementState
{
	UINT RoomID = 0;
	USHORT GameID = 0;
	UINT MapID = 0;
	std::vector<RankedSettlementEntry> Entries;
};

static UINT GetRankedGradeCode(const std::shared_ptr<ClientNode>& Client)
{
	if (!Client || Client->GradeLevel >= _countof(RankGradeLevel))
		return 0;
	return RankGradeLevel[Client->GradeLevel];
}

static RankedGradeSnapshot CaptureRankedGrade(const std::shared_ptr<ClientNode>& Client)
{
	RankedGradeSnapshot grade;
	if (!Client)
		return grade;
	grade.GradeLevel = GetRankedGradeCode(Client);
	grade.ChildLevel = Client->ChildLevel;
	grade.GradeScore = Client->GradeScore;
	grade.MaxGradeScore = getMaxScorce(grade.GradeLevel);
	grade.TotalScore = Client->TotalScore;
	return grade;
}

static bool RankedFinishTimeLess(
	const std::pair<std::shared_ptr<ClientNode>, PlayerRaceInfo>& lhs,
	const std::pair<std::shared_ptr<ClientNode>, PlayerRaceInfo>& rhs)
{
	const UINT lhsTime = lhs.second.FinishTime == 0 || lhs.second.FinishTime == 0xFFFFFFFF
		? 0xFFFFFFFE : lhs.second.FinishTime;
	const UINT rhsTime = rhs.second.FinishTime == 0 || rhs.second.FinishTime == 0xFFFFFFFF
		? 0xFFFFFFFE : rhs.second.FinishTime;
	return lhsTime == rhsTime ? lhs.second.Uin < rhs.second.Uin : lhsTime < rhsTime;
}

static bool PrepareRankedSettlement(const std::shared_ptr<RoomNode>& Room)
{
	if (!Room)
		return false;
	if (Room->RankedSettlement)
		return true;

	std::vector<std::pair<std::shared_ptr<ClientNode>, PlayerRaceInfo>> racers;
	for (size_t i = 0; i < Room->Player.size() && racers.size() < 6; ++i)
	{
		const std::shared_ptr<ClientNode>& Player = Room->Player[i];
		if (!Player || Player->TaskID != 0xFFFC || Player->Uin == 0)
			continue;
		PlayerRaceInfo race{};
		race.Uin = Player->Uin;
		race.FinishTime = Player->FinishTime > 0
			? static_cast<UINT>(Player->FinishTime) : 0xFFFFFFFF;
		race.Teamid = Player->TeamID;
		race.kartid = Player->KartSkinID > 0 ? Player->KartSkinID : Player->KartID;
		race.HighestSpeed = Player->HighestSpeed;
		race.CollisionCount = Player->CollisionCount;
		race.N2OGatherCount = Player->N2OGatherCount;
		race.DriftCount = Player->DriftCount;
		race.Detail = Player->RaceDetail;
		race.RankGradeLevel = GetRankedGradeCode(Player);
		race.DistanceToEnd = Player->LastDistanceToEnd;
		racers.emplace_back(Player, race);
	}
	if (racers.empty())
		return false;
	std::sort(racers.begin(), racers.end(), RankedFinishTimeLess);

	PlayerRaceInfo battleRecords[6]{};
	for (PlayerRaceInfo& record : battleRecords)
	{
		record.Uin = 0xFFFFFFFF;
		record.FinishTime = 0xFFFFFFFF;
	}
	for (size_t i = 0; i < racers.size(); ++i)
		battleRecords[i] = racers[i].second;
	InsertBattleRecord(battleRecords, Room->MapID, 4);

	std::shared_ptr<RankedSettlementState> settlement = std::make_shared<RankedSettlementState>();
	settlement->RoomID = Room->ID;
	settlement->GameID = Room->RaceGameID;
	settlement->MapID = Room->MapID;
	settlement->Entries.reserve(racers.size());
	for (size_t i = 0; i < racers.size(); ++i)
	{
		const std::shared_ptr<ClientNode>& Player = racers[i].first;
		const bool finished = racers[i].second.FinishTime != 0xFFFFFFFF;
		RankedSettlementEntry entry;
		entry.Player = Player;
		entry.Uin = Player->Uin;
		entry.FinishTime = racers[i].second.FinishTime;
		entry.KartID = racers[i].second.kartid;
		entry.TotalMoney = Player->Money > 0 ? static_cast<UINT>(Player->Money) : 0;
		entry.TotalExp = Player->Experience;
		entry.DistanceToEnd = Player->LastDistanceToEnd;
		entry.TeamID = static_cast<BYTE>(Player->TeamID);
		entry.LastGrade = CaptureRankedGrade(Player);

		if (finished)
		{
			AddSuperMoney(Player);
			if (raceAdd == 1)
				NotifyGenGameEndBoxAward(Player);
			if (Player->GuildID > 0)
			{
				PlayerDB_UpdateGuildListScore(Player->GuildID, GuildAdd, GuildAdd);
				PlayerDB_UpdateGuildInfoScore(Player->Uin, Player->GuildID, GuildAdd);
			}
		}

		entry.Compute.RankAddScore = finished ? GetRankAddScore(static_cast<USHORT>(i + 1)) : 0;
		entry.Compute.FinishAddScore = finished ? 1 : 0;
		const INT requestedGradeAdd = entry.Compute.RankAddScore + entry.Compute.FinishAddScore;
		const bool promotionWasActive = Player->PromotionMatch != 0 || Player->CurrentPromotionRoundNums != 0;
		int rankType = 0;
		if (requestedGradeAdd != 0 || promotionWasActive)
			rankType = RankRaceFunc(Player, static_cast<SHORT>(requestedGradeAdd), static_cast<UINT>(i + 1));
		entry.NewGrade = CaptureRankedGrade(Player);
		entry.Compute.GradeAddScore = static_cast<INT>(entry.NewGrade.TotalScore) -
			static_cast<INT>(entry.LastGrade.TotalScore);
		entry.Compute.GradeProtectAddScore = entry.Compute.GradeAddScore -
			entry.Compute.RankAddScore - entry.Compute.FinishAddScore;

		const bool promotionContext = promotionWasActive || rankType != 0 ||
			Player->PromotionMatch != 0 || Player->CurrentPromotionRoundNums != 0;
		if (promotionContext)
		{
			entry.Promo.PromotionMatch = Player->CurrentPromotionRoundNums == 0
				? static_cast<BYTE>(rankType) : static_cast<BYTE>(Player->PromotionMatch);
			entry.Promo.PromotionRoundNums = 5;
			entry.Promo.PromotionSuccessRoundNums = 3;
			entry.Promo.PromotionAlreadySuccessRoundNums =
				Player->CurrentPromotionWinRoundNums == 3 ? 3u : 0u;
			entry.Promo.PromotionRecordTag = GetPromotionRecordTag(
				Player->PromotionRecordTag, Player->CurrentPromotionRoundNums);
			entry.Promo.CurrentPromotionRoundNums = Player->CurrentPromotionRoundNums;
			if (Player->CurrentPromotionWinRoundNums == 3)
				entry.Promo.PromoSuccAddScore = 4;
			else if (Player->CurrentPromotionLoseRoundNums == 3)
				entry.Promo.PromoFailedMinusScore = -4;
		}

		if (Player->CurrentPromotionWinRoundNums == 3 || Player->CurrentPromotionLoseRoundNums == 3)
		{
			Player->PromotionRecordTag = 2;
			Player->PromotionMatch = 0;
			Player->CurrentPromotionRoundNums = 0;
			Player->CurrentPromotionWinRoundNums = 0;
			Player->CurrentPromotionLoseRoundNums = 0;
			PlayerDB_SetRankedInfo(Player);
		}

		settlement->Entries.emplace_back(std::move(entry));
	}
	Room->RankedSettlement = std::move(settlement);
	return true;
}

static void FinishRankedWireNode(BYTE* begin, BYTE*& end)
{
	const size_t len = end - begin;
	Set16(begin, static_cast<WORD>(len));
}

static void WriteRankedGradeSnapshot(BYTE*& p, const RankedGradeSnapshot& grade)
{
	BYTE* node = p;
	Write16(p, 0);
	Write32(p, grade.GradeLevel);
	Write32(p, grade.ChildLevel);
	Write32(p, grade.GradeScore);
	Write32(p, grade.MaxGradeScore);
	Write32(p, grade.TotalScore);
	FinishRankedWireNode(node, p);
}

static void WriteRankedPromoSnapshot(BYTE*& p, const RankedPromoSnapshot& promo)
{
	BYTE* node = p;
	Write16(p, 0);
	Write8(p, promo.PromotionMatch);
	Write32(p, promo.PromotionRoundNums);
	Write32(p, promo.PromotionSuccessRoundNums);
	Write32(p, promo.PromotionAlreadySuccessRoundNums);
	Write32(p, promo.PromotionRecordTag);
	Write32(p, promo.CurrentPromotionRoundNums);
	Write32(p, static_cast<UINT>(promo.PromoFailedMinusScore));
	Write32(p, static_cast<UINT>(promo.PromoSuccAddScore));
	Write8(p, promo.PromoDirectly);
	Write8(p, promo.GradeNoNeedPromo);
	Write8(p, promo.RankedMemoryNoNeedPromo);
	Write8(p, promo.PromotionExtraScore);
	Write8(p, promo.PromtRaceFailedDefendFlag);
	FinishRankedWireNode(node, p);
}

