static void WriteRankedProfessionLicenseAward(BYTE*& p)
{
	BYTE* node = p;
	Write16(p, 0);
	Write32(p, 0); // PointInc
	Write32(p, 0x80E8); // PointLevelCur
	Write32(p, 0x4074); // PointLevelMax
	Write16(p, 0x3018); // IncResultID
	Write8(p, 0); // ShowQiPao
	Write32(p, 0x1482); // PointWeekTotal
	Write32(p, 0); // PointWeekCur
	{
		BYTE* license = p;
		Write16(p, 0);
		Write8(p, 6); // BigLevel
		Write8(p, 5); // SmallLevel
		FinishRankedWireNode(license, p);
	}
	Write8(p, 1); // SwitchShowExtraAddPoint
	Write16(p, 0); // BeginOffsetSeconds
	FinishRankedWireNode(node, p);
}

static bool SelectRankedFrameForClient(
	const std::shared_ptr<ClientNode>& recipient,
	const std::shared_ptr<RoomNode>& Room,
	RankedGameFrameForward& forwarded)
{
	if (!recipient || !Room || !Room->RankedSettlement || !Room->RaceAuthorityValid)
		return false;
	for (const RankedSettlementEntry& entry : Room->RankedSettlement->Entries)
	{
		if (!entry.Player || entry.Uin == recipient->Uin)
			continue;
		std::lock_guard<std::mutex> lock(entry.Player->RankedGameFrameMutex);
		const RankedGameFrameReport& report = entry.Player->RankedFrameReport;
		if (!report.Valid || report.RoomID != Room->ID || report.GameID != Room->RaceGameID ||
			report.Uin != entry.Uin || report.MapID != Room->MapID ||
			report.GameSeqHigh != Room->RaceMatchSeqHigh ||
			report.GameSeqLow != Room->RaceMatchSeqLow || report.FrameNodes.empty())
			continue;
		forwarded.Valid = true;
		forwarded.RoomID = Room->ID;
		forwarded.GameID = Room->RaceGameID;
		forwarded.TargetUin = report.Uin;
		forwarded.MapID = report.MapID;
		forwarded.CheckPointID = report.CheckPointID;
		forwarded.FrameNodes = report.FrameNodes;
		return true;
	}
	return false;
}

static void WriteRankedGameFrameInfo(BYTE*& p, const RankedGameFrameForward& frame)
{
	BYTE* gameFrame = p;
	Write16(p, 0);
	Write32(p, frame.TargetUin);
	Write32(p, frame.MapID);
	Write16(p, 1); // FrameNum
	{
		BYTE* frameInfo = p;
		Write16(p, 0);
		Write16(p, frame.CheckPointID);
		Write32(p, static_cast<UINT>(frame.FrameNodes.size()));
		for (const auto& frameNode : frame.FrameNodes)
		{
			memcpy(p, frameNode.data(), frameNode.size());
			p += frameNode.size();
		}
		FinishRankedWireNode(frameInfo, p);
	}
	FinishRankedWireNode(gameFrame, p);
}

static void WriteOfficialRankedRaceScore(BYTE*& p, const RankedSettlementEntry& entry)
{
	BYTE* raceScore = p;
	Write16(p, 0);
	Write32(p, entry.Uin);
	Write32(p, entry.FinishTime);
	Write32(p, 0); // TP
	Write32(p, 0); // MoneyInc
	Write32(p, entry.TotalMoney);
	Write32(p, 0); // ExpInc
	Write32(p, entry.TotalExp);
	Write8(p, 0); // AwardNum: only server-produced awards may be listed
	Write32(p, 0); // TeamWorkExpInc
	Write32(p, 0); // PropPoint
	Write32(p, 0); // PropPointAddExp
	Write32(p, 0); // LuckyMatchPointInc
	Write32(p, 0); // LuckyMatchPointTotal
	Write32(p, 0); // LuckyMatchScoreInc
	Write32(p, 0); // LuckyMatchScoreTotal
	Write32(p, 0); // LuckMoneyInc
	Write32(p, 0); // LuckMoneyTotal
	Write32(p, 0); // GuildScoreInc
	Write8(p, 0); // CrazyPropAchieveNum
	Write32(p, 0); // IncWlMatchScore
	Write32(p, 0); // IncWlDegree
	Write8(p, 0); // IncItemNumByWl
	Write32(p, 0); // WlMutiplyCard
	Write32(p, 0); // SkateCoinInc
	Write32(p, 0); // SkateCoinTotal
	Write32(p, 0); // SkateCoinHistoryTotal
	Write32(p, 0); // TotalCoupons
	Write8(p, 0); // ChallengeCheer
	Write32(p, 0); // LoveValue
	Write32(p, 0); // SkateCoinEmperorBonus
	Write32(p, 0); // DetailRecordID
	Write8(p, 0); // HasGangsterResult
	{
		BYTE* activeKart = p;
		Write16(p, 0);
		Write8(p, 1); // HaveActiveInfo
		Write32(p, entry.KartID);
		Write32(p, 10); // ActiveLevel
		FinishRankedWireNode(activeKart, p);
	}
	Write8(p, 0); // HasWeRelayRaceOverInfo
	Write8(p, 0); // HaveSkatePropRaceInfo
	Write8(p, 0); // IsNewBox
	Write8(p, 0); // HaveArrestScoreInfo
	Write8(p, 1); // HasRankedMatchInfo
	{
		BYTE* rankedScore = p;
		Write16(p, 0);
		WriteRankedGradeSnapshot(p, entry.LastGrade);
		WriteRankedGradeSnapshot(p, entry.NewGrade);
		WriteRankedPromoSnapshot(p, entry.Promo);
		WriteRankedComputeSnapshot(p, entry.Compute);
		Write8(p, 0); // HavePromotionExtraScoreInfo
		FinishRankedWireNode(rankedScore, p);
	}

	Write8(p, 0); // HaveCrazyChaseScoreInfo
	Write8(p, entry.TeamID);
	Write8(p, 0); // HasRankedMatchArenaInfo
	Write32(p, entry.DistanceToEnd);
	Write8(p, 0); // ShortDistanceWinPoint
	Write8(p, 0); // Status
	Write8(p, 0); // HaveRankedMatchSpeedKingInfo
	Write8(p, 1); // ProfessionLicenseAwardNum
	WriteRankedProfessionLicenseAward(p);
	{
		BYTE* raceResult = p;
		Write16(p, 0);
		Write8(p, 0); // PLExpPowerValid
		Write8(p, 0); // PLHonorPowerValid
		Write8(p, 1); // ExpMultiNum
		Write8(p, 1); // HonorMultiNum
		FinishRankedWireNode(raceResult, p);
	}
	Write8(p, 0); // HaveRankedMatchExtraInfo
	Write8(p, 0); // HasYuLeJiaNianHuaComputeData
	Write32(p, 0); // WinStreak
	Write8(p, 0); // ParaNum
	FinishRankedWireNode(raceScore, p);
}

void NotifyRankedRaceOver(
	std::shared_ptr<ClientNode> Client,
	std::shared_ptr<RoomNode> Room,
	bool first)
{
	(void)first;
	if (!Client || !Room || !Room->RankedSettlement ||
		Room->RankedSettlement->RoomID != Room->ID ||
		Room->RankedSettlement->GameID != Room->RaceGameID)
	{
		QQS_DebugPrintf10001(
			"[RANKED-SETTLEMENT][513-SKIP] Uin=%u RoomID=%u Reason=state-not-prepared\n",
			Client ? Client->Uin : 0, Room ? Room->ID : 0);
		return;
	}

	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	const RankedSettlementState& settlement = *Room->RankedSettlement;
	Write8(p, static_cast<BYTE>(settlement.Entries.size()));
	for (const RankedSettlementEntry& entry : settlement.Entries)
		WriteOfficialRankedRaceScore(p, entry);

	Write8(p, 0); // WinTeamID
	Write32(p, 0); // WinType
	Write32(p, RankedOfficialAwardTimeMs);
	Write8(p, 0); // LuckyMatchResult
	Write8(p, 0); // LuckyMatchType
	Write8(p, 0); // HideTask PlayerNumber
	Write8(p, 0); // HasLadderMatchResult
	Write8(p, 0); // NeedFreshTutor
	Write8(p, 0); // HasMedalGameInfo
#ifndef ZingSpeed
	Write8(p, 0); // KickOffPlayerNumber
	Write8(p, 0); // EliminatedRacerNum
	Write8(p, 0); // TeamNum
	Write8(p, 0); // NPCRacerNum

	RankedGameFrameForward forwarded;
	const bool hasFrame = SelectRankedFrameForClient(Client, Room, forwarded);
	{
		std::lock_guard<std::mutex> lock(Client->RankedGameFrameMutex);
		Client->RankedFrameForward = hasFrame ? forwarded : RankedGameFrameForward{};
		Client->RankedFrameCheck = RankedGameFrameCheck{};
	}
	Write8(p, hasFrame ? 1 : 0);
	if (hasFrame)
		WriteRankedGameFrameInfo(p, forwarded);
	Write8(p, 0); // HasDesperateEscapeTrophyInfo
	Write8(p, 0); // HasGameStageInfo
#endif

	SendToClient(Client, 513, buf.data(), static_cast<DWORD>(p - buf.data()),
		Room->RaceGameID, FE_GAMELOGIC, 1, Notify);
}


