void NotifyBorderRaceOver2(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room, bool first)
{

	PlayerRaceInfo ArrPlayerRaceInfo[6] = {};
	for (int i = 0; i < 6; i++) {
		PlayerRaceInfo tmp{};
		tmp.Uin = -1;
		tmp.FinishTime = -1;
		ArrPlayerRaceInfo[i] = tmp;

		if (Room->Player[i]) {
			if (Room->Player[i]->FinishTime == 0) Room->Player[i]->FinishTime = -1;

			ArrPlayerRaceInfo[i].Uin = Room->Player[i]->Uin;
			ArrPlayerRaceInfo[i].FinishTime = Room->Player[i]->FinishTime;
			ArrPlayerRaceInfo[i].kartid = Room->Player[i]->KartSkinID > 0 ? Room->Player[i]->KartSkinID : Room->Player[i]->KartID;
			ArrPlayerRaceInfo[i].HighestSpeed = Room->Player[i]->HighestSpeed;
			ArrPlayerRaceInfo[i].CollisionCount = Room->Player[i]->CollisionCount;
			ArrPlayerRaceInfo[i].N2OGatherCount = Room->Player[i]->N2OGatherCount;
			ArrPlayerRaceInfo[i].DriftCount = Room->Player[i]->DriftCount;
			ArrPlayerRaceInfo[i].Detail = Room->Player[i]->RaceDetail;
			ArrPlayerRaceInfo[i].RankGradeLevel = RankGradeLevel[Room->Player[i]->GradeLevel];
		}
	}

	auto cmp_PlayerRaceInfo = [](PlayerRaceInfo& a, PlayerRaceInfo& b) -> bool {
		if (a.FinishTime == b.FinishTime) {
			return a.Uin < b.Uin;
		}
		else {
			return a.FinishTime < b.FinishTime;
		}
		};

	std::sort(ArrPlayerRaceInfo, ArrPlayerRaceInfo + 6, cmp_PlayerRaceInfo);

	if (first) {
		InsertBattleRecord(ArrPlayerRaceInfo, Room->MapID, 2);
	}

	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	size_t len;

	// 各种加成初始化
	int BabyAddValue = (Client->LoverBaby1EquipStat || Client->LoverBaby2EquipStat) ? 500 : 0;
	int EngageAddSuperMoney = 0;
	int NobleAdd = 0;
	int EmperorAdd = 0;
	int LoverVipAdd = 0;
	int GardenAddSuperMoney = 0;
	int GardenAddHonor = 0;
	int GuildVipAdd = 0;

	// 婚姻加成
	if (Client->EngageUin != 0) {
		EngageAddSuperMoney = 500;
	}

	// 皇族贵族加成
	if (Client->NoblePoint >= 30000) NobleAdd += 500;
	if (Client->NoblePoint >= 60000) NobleAdd += 500;

	// 钻皇贵族加成
	if (Client->EmperorPoint >= 30000) EmperorAdd += 1000;
	if (Client->EmperorPoint >= 60000) EmperorAdd += 1000;

	// 情侣贵族加成
	if (Client->LoverVipPoint >= 60000) LoverVipAdd = 1000;

	// 后花园系统加成
	if (Client->GardenPoint >= 60000) {
		GardenAddSuperMoney = 1000;
		GardenAddHonor = 10000;
	}

	// 车队贵族加成
	if (Client->GuildVipPoint >= 60000) GuildVipAdd = 500;

	// 计算最终的点券和荣誉加成
	int SuperMoney = Borderset[4] + BabyAddValue + EngageAddSuperMoney + NobleAdd + EmperorAdd + LoverVipAdd + GardenAddSuperMoney + GuildVipAdd;
	int Honor = Borderset[2] + GardenAddHonor;
	int HonorAdd = 0;
	int Experience = Borderset[3];

	// 玩家完成比赛的奖励加成
	if (Client->IsFinish == TRUE) {
		SelectClientExp(Client);

		// 高级道具增加荣誉加成
		for (int i = 0; i < BorderAdvancedCfg->AdvancedProp.size(); i++) {
			if (SelectSuperItem(Client, BorderAdvancedCfg->AdvancedProp[i].PropID)) {
				HonorAdd += BorderAdvancedCfg->AdvancedProp[i].Add;
			}
		}

		// 获取当前时间，确定是否应用倍数加成
		auto now = std::chrono::system_clock::now();
		std::time_t now_time = std::chrono::system_clock::to_time_t(now);
		struct tm* tm_now;
		localtime_s(tm_now, &now_time);
		int hour = tm_now->tm_hour;

		// 如果在倍数加成时间段内，应用边境倍数
		if (hour >= BorderTimes[2] && hour < BorderTimes[3] && BorderTimes[0] == 1) {
			SuperMoney *= BorderTimes[1];
			Experience *= BorderTimes[1];
			Honor *= BorderTimes[1];
		}
	/*	Honor += HonorAdd;*/

		//// 如果玩家有车队，加成的荣誉三倍
		//if (Client->GuildID > 0) {
		//	PlayerDB_UpdateGuildListScore(Client->GuildID, GuildAdd, GuildAdd);
		//	PlayerDB_UpdateGuildInfoScore(Client->Uin, Client->GuildID, GuildAdd);
		//	Honor *= 3;
		//}

		// 防止经验溢出
		Client->Experience = (Client->Experience > UINT_MAX - Experience) ? UINT_MAX : (Client->Experience + Experience);

		// 更新客户端的点券和荣誉
		Client->SuperMoney += SuperMoney;
		Client->TotalHonor += Honor;
		UpdateClientBase(Client);

		// 检查是否需要发放盲盒奖励
		if (raceAdd == 1) {
			NotifyGenGameEndBoxAward(Client);
		}
	}

	for (char i = 0; i < Room->CurrentPlayerNum; i++)
	{
		for (char i2 = 0; i2 < 6; i2++)
		{
			std::shared_ptr<ClientNode> RoomClient = Room->Player[i2];
			if (RoomClient)
			{
				if (RoomClient->ranknumber == i && RoomClient->IsFinish == TRUE)
				{

					BYTE* pp = BorderOver;
					pp += 2;
					Write32(pp, RoomClient->Uin);
					Write32(pp, RoomClient->FinishTime); //FinTime
					pp += 4;
					Write32(pp, Experience); //ExpInc
					Write32(pp, RoomClient->Experience); //TotalExp
					Write32(pp, SuperMoney); //SuperMoneyInc
					Write32(pp, RoomClient->SuperMoney); //TotalSuperMoney
					Write32(pp, Honor); //PersonalHonor
					//Write32(pp, 5000); //ExpInc
					//Write32(pp, RoomClient->Experience); //TotalExp
					//Write32(pp, 1000 + BabyAddValue); //SuperMoneyInc
					//Write32(pp, RoomClient->SuperMoney); //TotalSuperMoney
					//Write32(pp, 10000 + BabyAddValue + HonorAdd); //PersonalHonor
					Write32(pp, RoomClient->TotalHonor); //TotalPersonalHonor
					Write32(pp, 0); //NationalHonor
					Write32(pp, 0); //TotalNationalHonor
					memcpy(p, BorderOver, 177);
					p += 177;
					break;
				}
			}
		}
	}
	for (char i = 0; i < 6; i++)
	{
		std::shared_ptr<ClientNode> RoomClient = Room->Player[i];
		if (RoomClient)
		{
			if (RoomClient->IsFinish == FALSE)
			{
				BYTE* pp = BorderOver;
				pp += 2;
				Write32(pp, RoomClient->Uin);
				Write32(pp, -1); //FinTime
				pp += 4;
				Write32(pp, 0); //ExpInc
				Write32(pp, RoomClient->Experience); //TotalExp
				Write32(pp, 0); //SuperMoneyInc
				Write32(pp, RoomClient->SuperMoney); //TotalSuperMoney
				Write32(pp, 0); //PersonalHonor
				Write32(pp, RoomClient->TotalHonor); //TotalPersonalHonor
				Write32(pp, 0); //NationalHonor
				Write32(pp, 0); //TotalNationalHonor
				memcpy(p, BorderOver, 177);
				p += 177;
			}
		}
	}
	memcpy(p, "\x00\x00\x42\x68\x00\x04\x00\x00\x00\x00", 10);
	p += 10;
	len = p - buf.data();
	SendToClient(Client, 542, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}

void NotifyBorderRaceOver1(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room, bool first)
{

	PlayerRaceInfo ArrPlayerRaceInfo[6] = {};
	//PlayerRaceInfo ArrPlayerRaceInfo[6] = {};
	for (int i = 0; i < 6; i++)
	{
		PlayerRaceInfo tmp{};
		tmp.Uin = -1;
		tmp.FinishTime = -1;
		ArrPlayerRaceInfo[i] = tmp;

		if (Room->Player[i])
		{
			//完成时间如果是0还是会作为结算成绩进行排名
			//改为-1就是未完成了
			if (Room->Player[i]->FinishTime == 0)Room->Player[i]->FinishTime = -1;

			ArrPlayerRaceInfo[i].Uin = Room->Player[i]->Uin;
			//ArrPlayerRaceInfo[i].Round = room->Player[i]->Round;
			ArrPlayerRaceInfo[i].FinishTime = Room->Player[i]->FinishTime;

			ArrPlayerRaceInfo[i].kartid = Room->Player[i]->KartSkinID > 0 ? Room->Player[i]->KartSkinID : Room->Player[i]->KartID;

			ArrPlayerRaceInfo[i].HighestSpeed = Room->Player[i]->HighestSpeed;
			ArrPlayerRaceInfo[i].CollisionCount = Room->Player[i]->CollisionCount;
			ArrPlayerRaceInfo[i].N2OGatherCount = Room->Player[i]->N2OGatherCount;
			ArrPlayerRaceInfo[i].DriftCount = Room->Player[i]->DriftCount;
			ArrPlayerRaceInfo[i].Detail = Room->Player[i]->RaceDetail;

			ArrPlayerRaceInfo[i].RankGradeLevel = RankGradeLevel[Room->Player[i]->GradeLevel];
		}
	}

	auto cmp_PlayerRaceInfo = [](PlayerRaceInfo& a, PlayerRaceInfo& b) -> bool
		{
			if (a.FinishTime == b.FinishTime) {
				return  a.Uin < b.Uin;
			}
			else {
				return  a.FinishTime < b.FinishTime;
			}

		};

	//名次排序
	std::sort(ArrPlayerRaceInfo, ArrPlayerRaceInfo + 6, cmp_PlayerRaceInfo);

	if (first) {
		InsertBattleRecord(ArrPlayerRaceInfo, Room->MapID, 2);
	}

	std::vector<BYTE> buf(819200); BYTE* p = buf.data();
	//BYTE* p = buf;
	size_t len;

	//边境结算
	int BabyAddValue = 0;
	int HonorAdd = 0;
	int SuperMoney = 0;
	int Experience = 0;
	int Honor = 0;


	if (Client->LoverBaby1EquipStat || Client->LoverBaby2EquipStat)
	{
		BabyAddValue = 500;
	}


	if (Client->IsFinish == TRUE)
	{
		SelectClientExp(Client);
		//查看是否有超级道具效果
		for (int i = 0; i < BorderAdvancedCfg->AdvancedProp.size(); i++)
		{
			if (SelectSuperItem(Client, BorderAdvancedCfg->AdvancedProp[i].PropID)) {
				HonorAdd += BorderAdvancedCfg->AdvancedProp[i].Add;
			}
		}

		// 获取当前系统时间
		auto now = std::chrono::system_clock::now();
		std::time_t now_time = std::chrono::system_clock::to_time_t(now);
		struct tm* tm_now;
		localtime_s(tm_now, &now_time);

		// 获取小时
		int hour = tm_now->tm_hour;

		// 判断是否在时间内
		if (hour >= BorderTimes[2] && hour < BorderTimes[3] && BorderTimes[0] == 1) {
			SuperMoney = (Borderset[4] + BabyAddValue) * BorderTimes[1];
			Experience = Borderset[3] * BorderTimes[1];
			Honor = Borderset[2] * BorderTimes[1];
		}
		else
		{
			SuperMoney = (Borderset[4] + BabyAddValue);
			Experience = Borderset[3];
			Honor = Borderset[2];
		}
		Honor = Honor + HonorAdd;


		if (Client->GuildID > 0) {
			PlayerDB_UpdateGuildListScore(Client->GuildID, GuildAdd, GuildAdd);
			PlayerDB_UpdateGuildInfoScore(Client->Uin, Client->GuildID, GuildAdd);
			Honor = Honor * 3;
		}


		Client->Experience = (Client->Experience > UINT_MAX - Experience) ? UINT_MAX : Client->Experience + Experience;
		//Client->Experience += Experience;
		Client->SuperMoney += SuperMoney;
		Client->TotalHonor += Honor;//+10000荣誉
		UpdateClientBase(Client);

		if (raceAdd == 1) {
			NotifyGenGameEndBoxAward(Client);
		}
	}

	for (char i = 0; i < Room->CurrentPlayerNum; i++)
	{
		for (char i2 = 0; i2 < 6; i2++)
		{
			std::shared_ptr<ClientNode> RoomClient = Room->Player[i2];
			if (RoomClient)
			{
				if (RoomClient->ranknumber == i && RoomClient->IsFinish == TRUE)
				{

					BYTE* pp = BorderOver;
					pp += 2;
					Write32(pp, RoomClient->Uin);
					Write32(pp, RoomClient->FinishTime); //FinTime
					pp += 4;
					Write32(pp, Experience); //ExpInc
					Write32(pp, RoomClient->Experience); //TotalExp
					Write32(pp, SuperMoney); //SuperMoneyInc
					Write32(pp, RoomClient->SuperMoney); //TotalSuperMoney
					Write32(pp, Honor); //PersonalHonor
					//Write32(pp, 5000); //ExpInc
					//Write32(pp, RoomClient->Experience); //TotalExp
					//Write32(pp, 1000 + BabyAddValue); //SuperMoneyInc
					//Write32(pp, RoomClient->SuperMoney); //TotalSuperMoney
					//Write32(pp, 10000 + BabyAddValue + HonorAdd); //PersonalHonor
					Write32(pp, RoomClient->TotalHonor); //TotalPersonalHonor
					Write32(pp, 0); //NationalHonor
					Write32(pp, 0); //TotalNationalHonor
					memcpy(p, BorderOver, 177);
					p += 177;
					break;
				}
			}
		}
	}
	for (char i = 0; i < 6; i++)
	{
		std::shared_ptr<ClientNode> RoomClient = Room->Player[i];
		if (RoomClient)
		{
			if (RoomClient->IsFinish == FALSE)
			{
				BYTE* pp = BorderOver;
				pp += 2;
				Write32(pp, RoomClient->Uin);
				Write32(pp, -1); //FinTime
				pp += 4;
				Write32(pp, 0); //ExpInc
				Write32(pp, RoomClient->Experience); //TotalExp
				Write32(pp, 0); //SuperMoneyInc
				Write32(pp, RoomClient->SuperMoney); //TotalSuperMoney
				Write32(pp, 0); //PersonalHonor
				Write32(pp, RoomClient->TotalHonor); //TotalPersonalHonor
				Write32(pp, 0); //NationalHonor
				Write32(pp, 0); //TotalNationalHonor
				memcpy(p, BorderOver, 177);
				p += 177;
			}
		}
	}
	memcpy(p, "\x00\x00\x42\x68\x00\x04\x00\x00\x00\x00", 10);
	p += 10;
	len = p - buf.data();
	SendToClient(Client, 542, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}
void NotifyBorderRaceOver(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room, bool first)
{
	PlayerRaceInfo ArrPlayerRaceInfo[6] = {};
	std::vector<BorderRaceStartRosterEntry> borderRacePlayers;
	char playernum = 0;
	UINT slotUin[6] = { 0 };
	UINT slotGameID[6] = { 0 };
	UINT slotRoomID[6] = { 0 };
	UINT slotBorderRoomID[6] = { 0 };
	UINT slotTaskID[6] = { 0 };
	UINT slotFinishTime[6] = { 0 };
	int skippedSlotNum = 0;

	for (int i = 0; i < 6; i++) {
		PlayerRaceInfo tmp{};
		tmp.Uin = -1;
		tmp.FinishTime = -1;
		ArrPlayerRaceInfo[i] = tmp;
	}

	for (int i = 0; i < 6; i++) {
		std::shared_ptr<ClientNode> RoomClient = Room->Player[i];
		if (!RoomClient)
			continue;
		slotUin[i] = RoomClient->Uin;
		slotGameID[i] = RoomClient->GameID;
		slotRoomID[i] = RoomClient->RoomID;
		slotBorderRoomID[i] = RoomClient->BorderRoomID;
		slotTaskID[i] = RoomClient->TaskID;
		slotFinishTime[i] = RoomClient->FinishTime;
	}

	borderRacePlayers = BuildBorderRaceSettlementRoster(Room, &skippedSlotNum);
	std::stable_sort(borderRacePlayers.begin(), borderRacePlayers.end(),
		[](const BorderRaceStartRosterEntry& a, const BorderRaceStartRosterEntry& b)
		{
			const bool aFinished = a.Finished && a.FinishTime != 0 && a.FinishTime != 0xFFFFFFFF;
			const bool bFinished = b.Finished && b.FinishTime != 0 && b.FinishTime != 0xFFFFFFFF;
			if (aFinished != bFinished)
				return aFinished;
			if (aFinished && a.FinishTime != b.FinishTime)
				return a.FinishTime < b.FinishTime;
			return a.Uin < b.Uin;
		});
	if (borderRacePlayers.size() > static_cast<size_t>(BorderRaceScoreSlotCount)) {
		QQS_DebugPrintf10001("[FLOW][542-ROSTER-CLAMP] BorderRoomID=%u RacePlayerNum=%u Max=%d\n",
			Room->ID, static_cast<unsigned>(borderRacePlayers.size()), BorderRaceScoreSlotCount);
		borderRacePlayers.resize(BorderRaceScoreSlotCount);
	}

	playernum = (char)borderRacePlayers.size();
	for (char i = 0; i < playernum; i++)
	{
		const BorderRaceStartRosterEntry& raceEntry = borderRacePlayers[i];
		const bool finished = raceEntry.Finished && raceEntry.FinishTime != 0 && raceEntry.FinishTime != 0xFFFFFFFF;
		std::shared_ptr<ClientNode> LiveRoomClient = GetClient(raceEntry.Uin);
		if (IsBorderRacePlayerForRoom(Room, LiveRoomClient))
			LiveRoomClient->ranknumber = i;

		PlayerRaceInfo tmp{};
		tmp.Uin = raceEntry.Uin;
		tmp.FinishTime = finished ? raceEntry.FinishTime : (UINT)-1;
		tmp.Teamid = raceEntry.TeamID;
		tmp.kartid = raceEntry.KartSkinID > 0 ? raceEntry.KartSkinID : raceEntry.KartID;
		tmp.HighestSpeed = raceEntry.HighestSpeed;
		tmp.CollisionCount = raceEntry.CollisionCount;
		tmp.N2OGatherCount = raceEntry.N2OGatherCount;
		tmp.DriftCount = raceEntry.DriftCount;
		tmp.Detail = raceEntry.RaceDetail;
		tmp.RankGradeLevel = RankGradeLevel[raceEntry.GradeLevel];
		ArrPlayerRaceInfo[i] = tmp;
	}

	QQS_DebugPrintf10001("[FLOW][542-ROSTER] Uin=%u BorderRoomID=%u CurrentPlayerNum=%u RaceStartNum=%u ActiveMask=0x%04X RacePlayerNum=%u Skipped=%d Slots=[0:%u/G%u/R%u/B%u/T%u/F%u,1:%u/G%u/R%u/B%u/T%u/F%u,2:%u/G%u/R%u/B%u/T%u/F%u,3:%u/G%u/R%u/B%u/T%u/F%u,4:%u/G%u/R%u/B%u/T%u/F%u,5:%u/G%u/R%u/B%u/T%u/F%u]\n",
		Client->Uin, Room->ID, (unsigned)Room->CurrentPlayerNum, (unsigned)Room->RaceStartPlayerNum,
		(unsigned)Room->RaceActiveMask, (unsigned)playernum, skippedSlotNum,
		slotUin[0], slotGameID[0], slotRoomID[0], slotBorderRoomID[0], slotTaskID[0], slotFinishTime[0],
		slotUin[1], slotGameID[1], slotRoomID[1], slotBorderRoomID[1], slotTaskID[1], slotFinishTime[1],
		slotUin[2], slotGameID[2], slotRoomID[2], slotBorderRoomID[2], slotTaskID[2], slotFinishTime[2],
		slotUin[3], slotGameID[3], slotRoomID[3], slotBorderRoomID[3], slotTaskID[3], slotFinishTime[3],
		slotUin[4], slotGameID[4], slotRoomID[4], slotBorderRoomID[4], slotTaskID[4], slotFinishTime[4],
		slotUin[5], slotGameID[5], slotRoomID[5], slotBorderRoomID[5], slotTaskID[5], slotFinishTime[5]);

	// 如果是第一次结算，插入战斗记录
	if (first) {
		InsertBattleRecord(ArrPlayerRaceInfo, Room->MapID, 2);
	}

	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	size_t len;

	// 初始化各种加成
	int BabyAddValue = (Client->LoverBaby1EquipStat || Client->LoverBaby2EquipStat) ? 500 : 0; // 宝宝加成
	int EngageAddSuperMoney = (Client->EngageUin != 0) ? 500 : 0; // 婚姻加成
	int NobleAdd = 0;     // 皇族贵族加成
	int EmperorAdd = 0;   // 钻皇贵族加成
	int LoverVipAdd = 0;  // 情侣贵族加成
	int GardenAddSuperMoney = 0; // 后花园点券加成
	int GardenAddHonor = 0; // 后花园荣誉加成
	int GuildVipAdd = 0;   // 车队贵族加成

	// 皇族贵族加成
	if (Client->NoblePoint >= 30000) NobleAdd += 500;
	if (Client->NoblePoint >= 60000) NobleAdd += 500;

	// 钻皇贵族加成
	if (Client->EmperorPoint >= 30000) EmperorAdd += 1000;
	if (Client->EmperorPoint >= 60000) EmperorAdd += 1000;

	// 情侣贵族加成
	if (Client->LoverVipPoint >= 60000) LoverVipAdd = 1000;

	// 后花园系统加成
	if (Client->GardenPoint >= 60000) {
		GardenAddSuperMoney = 1000;
		GardenAddHonor = 10000;
	}

	// 车队贵族加成
	if (Client->GuildVipPoint >= 60000) GuildVipAdd = 500;

	// 计算基础奖励，之后再加上翻倍和贵族加成
	int BaseSuperMoney = Borderset[4];         // 基础点券奖励
	int BaseHonor = Borderset[2];              // 基础荣誉奖励
	int Experience = Borderset[3];             // 基础经验奖励
	int HonorAdd = 0;                          // 高级道具荣誉加成

	// 高级道具荣誉加成
	for (int i = 0; i < BorderAdvancedCfg->AdvancedProp.size(); i++) {
		if (SelectSuperItem(Client, BorderAdvancedCfg->AdvancedProp[i].PropID)) {
			HonorAdd += BorderAdvancedCfg->AdvancedProp[i].Add;
		}
	}

	// 检查是否在倍数加成时间段内，并应用倍数加成到基础奖励
	auto now = std::chrono::system_clock::now();
	std::time_t now_time = std::chrono::system_clock::to_time_t(now);
	struct tm tm_now;
	localtime_s(&tm_now, &now_time);
	int hour = tm_now.tm_hour;

	// 判断是否在倍数加成时间段内
	if (hour >= BorderTimes[2] && hour < BorderTimes[3] && BorderTimes[0] == 1) {
		BaseSuperMoney *= BorderTimes[1];  // 基础点券翻倍
		Experience *= BorderTimes[1];      // 基础经验翻倍
		BaseHonor *= BorderTimes[1];       // 基础荣誉翻倍
	}

	// 最终奖励计算：基础奖励（可能已翻倍） + 各种贵族和其他加成
	int SuperMoney = BaseSuperMoney + BabyAddValue + EngageAddSuperMoney + NobleAdd + EmperorAdd + LoverVipAdd + GardenAddSuperMoney + GuildVipAdd;
	int Honor = BaseHonor + GardenAddHonor + HonorAdd;  // 包括花园和道具的荣誉加成

	// 更新客户端的经验、点券和荣誉信息
	if (Client->IsFinish == TRUE) {
		SelectClientExp(Client); // 更新客户端经验
		Client->Experience = (Client->Experience > UINT_MAX - Experience) ? UINT_MAX : (Client->Experience + Experience); // 防止经验溢出
		Client->SuperMoney += SuperMoney;
		Client->TotalHonor += Honor;
		UpdateClientBase(Client); // 更新客户端的基础数据
		UpdateBorderRaceSnapshotFromClient(Room, Client, false, "border-542-reward");

		// 检查是否需要发放盲盒奖励
		if (raceAdd == 1) {
			NotifyGenGameEndBoxAward(Client);
		}
	}

	// 每个开赛车手严格生成一行，顺序即连续排名；不再按可残留/跳号的 ranknumber 扫六个槽位。
	int settlementRowNum = 0;
	for (const auto& raceEntry : borderRacePlayers) {
		const bool finished = raceEntry.Finished && raceEntry.FinishTime != 0 && raceEntry.FinishTime != 0xFFFFFFFF;
		UINT totalExperience = raceEntry.Experience;
		int totalSuperMoney = raceEntry.SuperMoney;
		int totalHonor = raceEntry.TotalHonor;
		std::shared_ptr<ClientNode> LiveRoomClient = GetClient(raceEntry.Uin);
		if (LiveRoomClient)
		{
			totalExperience = LiveRoomClient->Experience;
			totalSuperMoney = LiveRoomClient->SuperMoney;
			totalHonor = LiveRoomClient->TotalHonor;
		}
		BYTE borderRow[BorderRaceScoreWireSize] = {};
		memcpy(borderRow, BorderOver, BorderRaceScoreLegacyWireSize);
		Set16(borderRow, static_cast<WORD>(BorderRaceScoreWireSize));
		BYTE* pp = borderRow;
		pp += 2;
		Write32(pp, raceEntry.Uin);
		Write32(pp, finished ? raceEntry.FinishTime : (UINT)-1);
		pp += 4;
		Write32(pp, finished ? Experience : 0);
		Write32(pp, totalExperience);
		Write32(pp, finished ? SuperMoney : 0);
		Write32(pp, (UINT)totalSuperMoney);
		Write32(pp, finished ? Honor : 0);
		Write32(pp, (UINT)totalHonor);
		Write32(pp, 0); // NationalHonor
		Write32(pp, 0); // TotalNationalHonor
		memcpy(p, borderRow, sizeof(borderRow));
		p += sizeof(borderRow);
		settlementRowNum++;
	}

	// 当前客户端固定解码 6 个 RaceScore。未使用槽位必须写成 00 02；
	// 若直接接尾部，AwardTime 的 00 00 会被误读成第 N+1 行并渲染为空框。
	const int populatedRowNum = settlementRowNum;
	while (settlementRowNum < BorderRaceScoreSlotCount) {
		Write16(p, BorderRaceEmptyScoreWireSize);
		settlementRowNum++;
	}
	QQS_DebugPrintf10001("[FLOW][542-ROWS] Uin=%u BorderRoomID=%u Populated=%d Slots=%d RacePlayerNum=%u\n",
		Client->Uin, Room->ID, populatedRowNum, settlementRowNum, (unsigned)playernum);

	Write32(p, BorderOfficialAwardTimeMs); // AwardTime
	Write8(p, 0); // KickOffPlayerNumber
	Write8(p, 4); // BorderRaceType
	Write8(p, 0); // HasGameFrameInfo
	Write8(p, 0); // TeamNum
	len = p - buf.data();
	SendToClient(Client, 542, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}

