struct CustomRaceKartPhysChoice
{
	UINT VisualKartID = 0;
	UINT PhysLoadIDFor551 = 0;
	UINT PhysLoadedID = 0;
	bool PhysExactHit = false;
	bool PhysResolved = false;
};

static UINT PreferredCustomKartPhysLoadID(const std::shared_ptr<ClientNode>& Player)
{
	if (!Player)
		return 0;
	if (Player->KartSkinID > 0)
		return Player->KartSkinID;
	return Player->KartID;
}

static CustomRaceKartPhysChoice ResolveCustomRaceKartPhysChoice(const std::shared_ptr<RoomNode>& Room, const std::shared_ptr<ClientNode>& Player)
{
	CustomRaceKartPhysChoice choice;
	const UINT preferredID = PreferredCustomKartPhysLoadID(Player);
	const UINT baseKartID = Player ? Player->KartID : 0;
	choice.VisualKartID = preferredID;
	choice.PhysLoadIDFor551 = preferredID;

	if (preferredID != 0)
	{
		std::vector<unsigned char> materializedData;
		if (TryBuildKartPhysDataForPlayer(preferredID, Player, Player, materializedData))
		{
			choice.PhysLoadedID = preferredID;
			choice.PhysExactHit = true;
			choice.PhysResolved = true;
		}
	}

	QQS_DebugPrintf10001("[FLOW][CUSTOM-KARTPHYS-RESOLVE] Uin=%u RoomID=%u KartID=%u SkinID=%u VisualKart=%u LoadID=%u LoadedID=%u Exact=%d Resolved=%d\n",
		Player ? Player->Uin : 0, Room ? Room->ID : 0, baseKartID, Player ? Player->KartSkinID : 0,
		choice.VisualKartID, choice.PhysLoadIDFor551, choice.PhysLoadedID,
		choice.PhysExactHit ? 1 : 0, choice.PhysResolved ? 1 : 0);
	return choice;
}

