void RequestUseProp2(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (!Client || !Body || BodyLen < sizeof(USHORT))
	{
		return;
	}

	const size_t payloadLength = BodyLen - sizeof(USHORT);
	qqspeed::useprop::Request165 request;
	std::string parseError;
#ifdef ZingSpeed
	const auto flavor = qqspeed::useprop::Request165Flavor::ZingSpeed;
#else
	const auto flavor = qqspeed::useprop::Request165Flavor::QqSpeed21487;
#endif
	if (!qqspeed::useprop::ParseRequest165(
			reinterpret_cast<const std::uint8_t*>(Body),
			payloadLength,
			flavor,
			request,
			&parseError))
	{
		return;
	}

	// Msg165 is a player-authored request, but its Uin must still match the
	// authenticated connection. Do not rewrite a mismatch and continue.
	if (request.uin == 0 || request.uin != Client->Uin)
		return;

	std::shared_ptr<ClientNode> stateClient;
	std::shared_ptr<RoomNode> Room;
	if (!ResolveActiveRaceStateClient(Client, request.uin, stateClient, Room))
		return;
	Client = stateClient;

	Client->PropID = request.propId;
	if (request.propId == 34)
	{
		Client->SuperJet = 0;
	}
	if (request.propId == 759)
	{
		Client->getPropNum = 0;
	}
	if ((Client->TaskID == 0xFFFC && !rankstone) || Client->TaskID == 0xFFF1)
	{
		return;
	}
	Client->PropIndex = request.propIndex;

	if (Client->GameID == 0 || Client->GameID == 0xFFFF)
		return;

	// C2S Msg165 的 StoneSkillType=-1 是普通氮气的正常值。
	// 重生宝珠由服务端读取已装备宝石和 Msg800 同源 YML，完成次数、冷却及概率判定。
	TryActivateServerSkillStone(
		Client,
		request.propId,
		static_cast<std::int32_t>(request.propIndex));

	// ParaList/Status/PassedCheckPointIDs are server-result fields, not Msg165
	// request bytes. The explicit empty/success result matches all 268 captured
	// QQSpeed 21487 front-spray Msg517 packets (PropID 1 and 777).
	const qqspeed::useprop::AuthoritativeUsePropResult result;
	const qqspeed::useprop::Notify517 notify =
		qqspeed::useprop::MakeNotify517(request, result);
	std::vector<std::uint8_t> notifyBody;
	std::string serializeError;
	if (!qqspeed::useprop::SerializeNotify517(notify, notifyBody, &serializeError))
	{
		return;
	}

	const short sourceGameID = static_cast<short>(Client->GameID);
	const int seatLimit = GetRoomSeatLimit(Room);
	for (int seat = 0; seat < seatLimit && seat < static_cast<int>(Room->Player.size()); ++seat)
	{
		const std::shared_ptr<ClientNode>& RoomClient = Room->Player[seat];
		if (!RoomClient || RoomClient == Client || RoomClient->deleteflag || !RoomClient->IsLogin)
		{
			continue;
		}

		const USHORT receiverPlayerID = GetRoomConnPlayerID(Room, RoomClient);
		if (!IsValidWireConnID16(receiverPlayerID))
		{
			continue;
		}
		SendToClientWithWireDstID(
			RoomClient,
			517,
			reinterpret_cast<const BYTE*>(notifyBody.data()),
			static_cast<DWORD>(notifyBody.size()),
			sourceGameID,
			FE_GAMELOGIC,
			static_cast<short>(receiverPlayerID),
			Notify);
	}
}

