void ResponseAddToMatchQueue(std::shared_ptr<ClientNode> Client, USHORT matchQueueType)
{
	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;
	const bool isAuroraQueue = Client && matchQueueType == 8 &&
		Client->AuroraPendingWorkID != 0;

	Write16(p, 0); //resultId
	Write8(p, 0); //reasonLen
	Write16(p, matchQueueType); //matchQueueType
	Write32(p, 0); //Para0
	Write8(p, isAuroraQueue ? 1 : 0); //IsAllArea
	Write32(p, 0); //MapID
	if (isAuroraQueue)
		Write32(p, 0); // m_iPara1; present in official Aurora 20079

	len = p - buf.data();
	SendToClient(Client, 20079, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);
}

void NotifyCustomMatchAck(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room)
{
	if (!Client || !Room)
		return;

	std::vector<BYTE> buf(32); BYTE* p = buf.data(); size_t len;

	// SendToClient writes the 2-byte wire BodyLen. The reference wire body is:
	// 00 0A <RoomID> 00 01 <Uin>. 0x0338 in pcaps/3/new was only that room's ID,
	// not a constant. If this does not match the current room, the client will
	// ignore the front matching UI and appear to "freeze in room" for the delay.
	Write16(p, (USHORT)Room->ID);
	Write16(p, 0x0001);
	// pcaps/3/new 20213 tail is the room/player identity (e.g. 0x274c),
	// not the logical ServerID.  Using ServerID=112 here makes the client
	// ignore the match-ui ACK and skip straight toward loading.
	Write32(p, Client->Uin);

	len = p - buf.data();
	QQS_DebugPrintf10001("[FLOW][20213-CUSTOM] send match ack Uin=%u RoomID=%u AckIdentity=%u ServerID=%u SrcFE=ROOM PayloadLen=%zu WireBodyLen=%zu\n",
		Client->Uin, Room->ID, Client->Uin, Client->ServerID, len, len + 2);
	SendToClient(Client, 20213, buf.data(), len, Room->ID, FE_ROOM, 1, Notify);
}

bool NotifyMatchResult(std::shared_ptr<ClientNode> Client, USHORT matchQueueType)
{
	std::shared_ptr<RoomNode> Room = GetActiveRaceRoom(Client);
	if (!Client || !Room || !Room->RaceAuthorityValid ||
		Room->RaceMatchSeqHigh == 0 || Room->RaceMatchSeqLow == 0 ||
		Room->RaceSeed == 0 || Room->RaceGameID == 0)
	{
		QQS_DebugPrintf10001("[FLOW][20081-ABORT] Uin=%u RoomID=%u Queue=%u Reason=missing-race-authority\n",
			Client ? Client->Uin : 0, Room ? Room->ID : 0, static_cast<unsigned>(matchQueueType));
		return false;
	}
	const bool rankedRoom = matchQueueType == 0x0A && Room->matchQueueType == 0x0A;
	const USHORT gameServerRoute = rankedRoom ? Room->ServerID : Room->RaceGameID;
	if (gameServerRoute == 0 || (rankedRoom && (gameServerRoute < 110 || gameServerRoute > 113)))
	{
		QQS_DebugPrintf10001(
			"[FLOW][20081-ABORT] Uin=%u RoomID=%u Queue=%u GameSvrID=%u Reason=invalid-game-server-route\n",
			Client->Uin, Room->ID, static_cast<unsigned>(matchQueueType),
			static_cast<unsigned>(gameServerRoute));
		return false;
	}
	std::string enterIP = IP;
	USHORT enterTcpPort = TcpPort;
	USHORT enterUdpPort = UdpPort;
	try
	{
		const YAML::Node testConfig = YAML::LoadFile(".\\Config\\config.yml")["CrossServerTest"];
		if (testConfig && testConfig["Enabled"] && testConfig["Enabled"].as<bool>())
		{
			enterIP = testConfig["WorkerIP"].as<std::string>();
			enterTcpPort = testConfig["WorkerTcpPort"].as<USHORT>();
			enterUdpPort = testConfig["WorkerUdpPort"].as<USHORT>();
		}
	}
	catch (const std::exception& exception)
	{
		QQS_DebugPrintf10001(
			"[FLOW][20081-ABORT] Uin=%u RoomID=%u Queue=%u Reason=cross-server-config Error=%s\n",
			Client->Uin, Room->ID, static_cast<unsigned>(matchQueueType), exception.what());
		return false;
	}

	IN_ADDR endpointAddress{};
	const int endpointParseResult = enterIP.empty()
		? 0
		: InetPtonA(AF_INET, enterIP.c_str(), &endpointAddress);
	const UINT endpointIP = endpointAddress.S_un.S_addr;
	if (endpointParseResult != 1 || endpointIP == INADDR_NONE || endpointIP == INADDR_ANY ||
		enterTcpPort == 0 || enterUdpPort == 0)
	{
		QQS_DebugPrintf10001("[FLOW][20081-ABORT] Uin=%u RoomID=%u Queue=%u Reason=invalid-enter-endpoint IP=%s TCP=%u UDP=%u\n",
			Client->Uin, Room->ID, static_cast<unsigned>(matchQueueType), enterIP.c_str(),
			static_cast<unsigned>(enterTcpPort), static_cast<unsigned>(enterUdpPort));
		return false;
	}

	std::vector<BYTE> buf(256);
	BYTE* p = buf.data();
	Write16(p, 0); // ResultID
	Write16(p, 0); // ReasonLen
	Write8(p, static_cast<BYTE>(matchQueueType));
	Write8(p, 1); // HasEnterInfo
	{
		BYTE* enterInfo = p;
		Write16(enterInfo, 0);
		{
			BYTE* addrInfo = enterInfo;
			Write16(addrInfo, 0);
			// 官服 AddrInfo 的 SvrID 是随后发送 548 的 GAMESVRD 路由，
			// 不是本局 GAMELOGIC 会话 ID。SvrIP 按 inet_addr 的主机数值
			// 写入；抓包线字节因此看起来是点分 IP 的逆序。
			Write16(addrInfo, gameServerRoute);
			Write32(addrInfo, endpointIP);
			Write8(addrInfo, 1);
			Write16(addrInfo, enterTcpPort);
			Write8(addrInfo, 1);
			Write16(addrInfo, enterUdpPort);
			Write8(addrInfo, 0); // This server publishes one concrete endpoint.
			const size_t addrLen = static_cast<size_t>(addrInfo - enterInfo);
			Set16(enterInfo, static_cast<WORD>(addrLen));
			enterInfo += addrLen;
		}
		Write32(enterInfo, Room->ID);
		Write16(enterInfo, 0); // SceneID
		const size_t enterLen = static_cast<size_t>(enterInfo - p);
		Set16(p, static_cast<WORD>(enterLen));
		p += enterLen;
	}

	Write32(p, Room->MapID);
	Write16(p, 1); // MatchedRoomType
	Write16(p, 0); // TeamMatchType
	Write8(p, 1); // PVPType
	Write32(p, Room->RaceSeed); // PVPKey
	Write32(p, Room->RaceMatchSeqHigh);
	Write32(p, Room->RaceMatchSeqLow);
	Write16(p, 0); // ForceTransCount
	Write16(p, 1); // PlayerMatchingType
	Write8(p, 4);
	for (int i = 0; i < 4; ++i)
		Write32(p, 0);

	const size_t len = static_cast<size_t>(p - buf.data());
	const BOOL sent = SendToClient(
		Client, 20081, buf.data(), static_cast<DWORD>(len),
		Client->ConnID, FE_PLAYER, 1, Notify);
	QQS_DebugPrintf10001("[FLOW][20081] Uin=%u RoomID=%u Queue=%u MapID=%u PVPKey=%u Seq=%u/%u GameSvrID=%u Endpoint=%s:%u PayloadLen=%zu Sent=%d\n",
		Client->Uin, Room->ID, static_cast<unsigned>(matchQueueType), Room->MapID,
		Room->RaceSeed, Room->RaceMatchSeqHigh, Room->RaceMatchSeqLow,
		static_cast<unsigned>(gameServerRoute), enterIP.c_str(),
		static_cast<unsigned>(enterTcpPort), len, sent ? 1 : 0);
	return sent != FALSE;
}


static void SetCustomStageU32LE(BYTE* ptr, DWORD value)
{
	ptr[0] = static_cast<BYTE>(value & 0xFF);
	ptr[1] = static_cast<BYTE>((value >> 8) & 0xFF);
	ptr[2] = static_cast<BYTE>((value >> 16) & 0xFF);
	ptr[3] = static_cast<BYTE>((value >> 24) & 0xFF);
}

void NotifyCustomStageEvent1727(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room, BYTE StageIndex)
{
	if (!Client || !Room || !Room->HasCustomScheme)
		return;

	std::vector<BYTE> buf(64); BYTE* p = buf.data(); size_t len;
	BYTE* payload = p;
	// pcaps\7 custom 1727 payload, excluding the leading wire body length 0028.
	WriteHex(p, "74D9BBA0007A00000074D9BBA000000000030000000000000001000000010000000000000000");

	len = p - buf.data();
	BYTE stageCount = GetCustomStageCount(Room);
	if (StageIndex >= stageCount)
		StageIndex = (BYTE)(stageCount - 1);
	BYTE nextStageIndex = (StageIndex + 1 < stageCount) ? (BYTE)(StageIndex + 1) : StageIndex;

	if (len >= 38) {
		Set32(payload + 0, Client->Uin);
		Set32(payload + 9, Client->Uin);
		Set8(payload + 17, 3);
		SetCustomStageU32LE(payload + 21, StageIndex);
		SetCustomStageU32LE(payload + 25, nextStageIndex);
		SetCustomStageU32LE(payload + 29, 1);
	}

	QQS_DebugPrintf10001("[FLOW][1727-CUSTOM] Uin=%u RoomID=%u StageIndex=%u NextStage=%u CustomMapNum=%u PayloadLen=%zu WireBodyLen=%zu\n",
		Client->Uin, Room->ID, StageIndex, nextStageIndex, stageCount, len, len + 2);
	SendToClient(Client, 1727, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}

void NotifyCustomMatchResult(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room)
{
	if (!Client || !Room || !Room->RaceAuthorityValid ||
		Room->RaceMatchSeqHigh == 0 || Room->RaceMatchSeqLow == 0)
	{
		QQS_DebugPrintf10001("[FLOW][20081-CUSTOM-ABORT] Uin=%u RoomID=%u Reason=missing-race-authority\n",
			Client ? Client->Uin : 0, Room ? Room->ID : 0);
		return;
	}

	std::vector<BYTE> buf(64); BYTE* p = buf.data(); size_t len;

	// Compact NotifyMatchResult. SendToClient writes the 2-byte wire BodyLen,
	// so this 32-byte payload becomes the pcaps/3/new 34-byte wire body:
	// 00 22 00 00 00 00 08 00  00 00 01 c0 00 01 00 0e
	// 01 PV PV PV PV  HH HH HH HH  LL LL LL LL  00 00 00 00  00
	// HasEnterInfo=0 so EnterInfo block is skipped, then mapID/match config follow.
	// Keep custom-match identity stable for all players in the same room.
	// If these are per-client random/tick values, the room UI can show a changed room id after start.
	UINT pvpKey = Room->ID;
	UINT gameSeqHigh = Room->RaceMatchSeqHigh;
	UINT gameSeqLow = Room->RaceMatchSeqLow;
	UINT matchScene = 0x000001c0; // mirror reference; client treats this as match-room scene tag

	Write16(p, 0);                  // ResultID
	Write16(p, 0);                  // ReasonLen
	Write8(p, 8);                   // MatchQueueType=8
	Write8(p, 0);                   // HasEnterInfo=0 (no addr info)
	Write32(p, matchScene);         // mapID/matchScene placeholder, must mirror reference
	Write16(p, 1);                  // MatchedRoomType
	Write16(p, 14);                 // TeamMatchType / AllocSvrType
	Write8(p, 1);                   // PVPType
	Write32(p, pvpKey);             // PVPKey
	Write32(p, gameSeqHigh);        // GameSeqIDHigh
	Write32(p, gameSeqLow);         // GameSeqIDLow
	Write16(p, 0);                  // ForceTransCount=0
	Write16(p, 0);                  // PlayerMatchingType=0
	Write8(p, 0);                   // paraNum=0

	len = p - buf.data();
	QQS_DebugPrintf10001("[FLOW][20081-CUSTOM-v5-compact] send compact match result Uin=%u RoomID=%u MapID=%u Scene=0x%08x PVPKey=%u Seq=%u/%u PayloadLen=%zu WireBodyLen=%zu ServerID=%u SrcFE=ROOM\n",
		Client->Uin, Room->ID, Room->MapID, matchScene, pvpKey, gameSeqHigh, gameSeqLow, len, len + 2, Client->ServerID);
	SendToClient(Client, 20081, buf.data(), len, Room->ID, FE_ROOM, 1, Notify);
}

