void RequestLeaveGame(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{

	//请求退出游戏
	UINT uin = Read32(Body);
	UINT time = Read32(Body);

	UINT GameSeqIDHigh = Read32(Body);
	UINT GameSeqIDLow = Read32(Body);
	USHORT LeaveGameType = Read16(Body);

	if (TryHandleLuckyMatchLeaveGame(Client, LeaveGameType))
		return;

	if (Client && (Client->SpeedLadderRacePending || Client->SpeedLadderRaceActive))
		SpeedLadder_ClearRaceContext(Client, "leave-game");

	if (LeaveGameType == 3 && Client->TaskID == 0xFFF1) {
		//请求退出打榜
		ResponseLeaveGame(Client);
		NotifyRaceShow(Client);
		NotifyG2CChallengeResult(Client, 4, -1);
		/*if (Client->ChallengeMaps.size() == 1) {
			UpdateChallengeMapStatus(Client->ChallengeMaps[0].MapID, Client->ChallengeMaps[0].RankID, 0);
		}*/
	}
	//UCHAR ParaNum = Read8(Body);
	//int[] ParaList[] = Read32(Body);
	//int ParaList[1];
	//ParaList[0] = Client->MapID;
	//ResponseLeaveGame(Client);

	std::shared_ptr<RoomNode> Room = nullptr;
	std::shared_ptr<RoomNode> BorderRoom = nullptr;
	if (Client && Client->RoomID != 0)
		Room = GetRoom(Client->RoomID);
	if (Client && Client->BorderRoomID != 0)
		BorderRoom = GetBorderRoom(Client->BorderRoomID);

	std::shared_ptr<RoomNode> RaceRoom = BorderRoom ? BorderRoom : Room;
	bool raceRoomIsBorder = (BorderRoom != nullptr && RaceRoom == BorderRoom);
	if (RaceRoom && raceRoomIsBorder)
	{
		const char* reason = "leave-game-border-esc-official";
		// 边境 ESC 与普通多人房一样由客户端继续驱动：
		// 424(C2S) -> 514(ReturnHall=0,Wait=0,map) -> 105 -> 102(hall)。
		// 不能在 424 内立即清 BorderRoom；否则主动 105 会丢失房间上下文，
		// 客户端也不会发出后续 105/102。
		if (!SendLeaveGameEscToRoom514(Client, RaceRoom, LeaveGameType, 0, reason))
			return;
		BeginOfficialEscFlow(Client, RaceRoom, false, true, reason);
		QQS_DebugPrintf10001("[FLOW][ESC-BORDER-HALL-ARMED] Uin=%u ReqUin=%u BorderRoomID=%u LeaveGameType=%u StartNum=%u ActiveMask=0x%04X CurrentPlayerNum=%u ReturnHall=0 WaitEnterRoom=0 Response424=0 NextAfter105=102\n",
			Client ? Client->Uin : 0, uin, RaceRoom->ID, LeaveGameType,
			RaceRoom->RaceStartPlayerNum, (unsigned)RaceRoom->RaceActiveMask,
			(unsigned)RaceRoom->CurrentPlayerNum);
		Client->IsFinish = 0;
		Client->IsReady = 0;
		return;
	}

	if (RaceRoom && Room)
	{
		const bool singleRace = IsSinglePlayerRace(RaceRoom);
		const bool customReturnRoom = IsCustomReturnRoom(Room);
		const bool twelveReturnRoom = customReturnRoom && IsTwelvePlayerReturnRoom(Room);

		// 3D 房有独立的建房/Outdoor 回包链，保留原行为，不套普通竞速房样本。
		if (singleRace && customReturnRoom && Room->ChatRoomType == 6)
		{
			ReturnLeaveGameTo3DRoom(Client, Room, LeaveGameType, "leave-game-single-3d-room");
			Client->IsFinish = 0;
			Client->IsReady = 0;
			return;
		}

		if (customReturnRoom)
		{
			if (singleRace)
			{
				const char* reason = twelveReturnRoom
					? "leave-game-12p-custom-single-room"
					: "leave-game-custom-single-room";
				QQS_DebugPrintf10001("[FLOW][ESC-CUSTOM-ROOM] Uin=%u RoomID=%u LeaveGameType=%u StartNum=%u ActiveMask=0x%04X CurrentPlayerNum=%u Is12=%d ReturnHall=0 WaitEnterRoom=1\n",
					Client ? Client->Uin : 0, Room->ID, LeaveGameType,
					(unsigned)Room->RaceStartPlayerNum, (unsigned)Room->RaceActiveMask,
					(unsigned)Room->CurrentPlayerNum, twelveReturnRoom ? 1 : 0);

				// 自定义单人 ESC 直接重建原房：514(wait=1) -> 104 -> 客户端 AT=62。
				// 这条链会取消计时器并重置房间运行态，必须与 OnTimer/OnBegin 串行。
				std::unique_lock<std::shared_mutex> roomStateLock(Room->mutex);
				if (!SendLeaveGameEscToRoom514(Client, Room, LeaveGameType, 1, reason))
					return;
				ReturnClientToOriginalRoom(Client, Room, reason, true);
			}
			else
			{
				const char* reason = twelveReturnRoom
					? "leave-game-12p-custom-multi-esc-hall"
					: "leave-game-custom-multi-esc-hall";
				QQS_DebugPrintf10001("[FLOW][ESC-CUSTOM-HALL] Uin=%u RoomID=%u LeaveGameType=%u StartNum=%u ActiveMask=0x%04X CurrentPlayerNum=%u Is12=%d ReturnHall=1 WaitEnterRoom=0\n",
					Client ? Client->Uin : 0, Room->ID, LeaveGameType,
					(unsigned)Room->RaceStartPlayerNum, (unsigned)Room->RaceActiveMask,
					(unsigned)Room->CurrentPlayerNum, twelveReturnRoom ? 1 : 0);
				SendLeaveGameToHall514(Client, Room, LeaveGameType, reason);
				if (Room->ChatRoomType == 6)
					ResponseCreateRoom(Client, Room, 0);
				LeaveRoom(Client, 0);
			}

			Client->IsFinish = 0;
			Client->IsReady = 0;
			return;
		}

		const char* reason = singleRace
			? "leave-game-single-official"
			: "leave-game-multi-official";

		// 官服普通竞速房 ESC 样本：
		//   single: 424(C2S) -> 514(ReturnHall=0,Wait=0,map) -> 424(S2C)
		//           -> 105 -> 105(duplicate) -> 103(create room)
		//   multi : 424(C2S) -> 514(ReturnHall=0,Wait=0,map)
		//           -> 105 -> 102(room list)，没有 424(S2C)。
		// 两条链都必须等客户端 105 才真正离房；多人剩余赛局由 LeaveRoom
		// 里的 HandlePlayerLeaveRace 清活动位，RaceStartPlayerNum 保留开赛历史值。
		if (!SendLeaveGameEscToRoom514(Client, Room, LeaveGameType, 0, reason))
			return;
		BeginOfficialEscFlow(Client, Room, singleRace, false, reason);
		if (singleRace)
		{
			ResponseLeaveGame(Client);
			PrepareOfficialSingleEscWait105(Client, Room, reason);
		}

		QQS_DebugPrintf10001("[FLOW][ESC-OFFICIAL-ARMED] Uin=%u RoomID=%u LeaveGameType=%u Single=%d StartNum=%u ActiveMask=0x%04X CurrentPlayerNum=%u HasCustom=%d Is12=%d ReturnHall=0 WaitEnterRoom=0 Response424=%d NextAfter105=%u\n",
			Client ? Client->Uin : 0, Room->ID, LeaveGameType, singleRace ? 1 : 0,
			(unsigned)Room->RaceStartPlayerNum, (unsigned)Room->RaceActiveMask,
			(unsigned)Room->CurrentPlayerNum, Room->HasCustomScheme ? 1 : 0,
			twelveReturnRoom ? 1 : 0, singleRace ? 1 : 0, singleRace ? 103 : 102);
		Client->IsFinish = 0;
		Client->IsReady = 0;
		return;
	}

	NotifyGameOver(Client, 0, 0, 0);
	LeaveBorderRoom(Client, 0);
	Client->IsFinish = 0;
	Client->IsReady = 0;

}

void ResponseLeaveGame(std::shared_ptr<ClientNode> Client)
{
	if (!Client)
		return;

	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;

	Write32(p, Client->Uin); //Uin
	Write16(p, 0); //ResultID

	len = p - buf.data();
	int inboundWireMsgSeq = -1;
	int inboundProtocolSeq = -1;
	if (!TryGetCurrentInboundWireMsgSeq(Client, inboundWireMsgSeq) || inboundWireMsgSeq < 0 ||
		!TryGetCurrentInboundProtocolSeq(Client, inboundProtocolSeq) || inboundProtocolSeq < 0)
	{
		QQS_DebugPrintf10001("[FLOW][424-LEAVE-GAME-ACK-ABORT] Uin=%u GameID=%u Reason=missing-inbound-response-correlation WireMsgSeq=%d ProtocolSeq=%d\n",
			Client->Uin, Client->GameID, inboundWireMsgSeq, inboundProtocolSeq);
		return;
	}
	SendCorrelatedResponseToClient(
		Client, 424, buf.data(), static_cast<DWORD>(len),
		Client->GameID, FE_GAMELOGIC, GetClientWirePlayerHeaderID(Client),
		inboundWireMsgSeq, inboundProtocolSeq);
}


void NotifyRandRoomNameList(std::shared_ptr<ClientNode> Client)
{

	/*std::string Byte = "";
	const unsigned char* Msg760 = EHexToByte(Byte.data());
	SendToClient(Client, 760, (const BYTE*)Msg760, Byte.length() / 2, Client->ConnID, FE_PLAYER, 1, Notify);
	delete[] Msg760;
	return;*/

	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;

	const char* RandRoomNameList[] = { "RandRoomName A","RandRoomName B","RandRoomName C" };
	BYTE Count = sizeof(RandRoomNameList) / sizeof(RandRoomNameList[0]);
	Write8(p, Count);
	for (BYTE i = 0; i < Count; i++)
	{ //RoomNames
		BYTE* pRoomNames = p;
		Write16(pRoomNames, 0); //len

		len = strlen(RandRoomNameList[i]);
		Write8(pRoomNames, (BYTE)len); //NameLen
		memcpy(pRoomNames, RandRoomNameList[i], len);
		pRoomNames += len;

		for (size_t i = 0; i < 20; i++)
		{
			Write8(pRoomNames, 0); //BaseModes[]
		}

		len = pRoomNames - p;
		Set16(p, (WORD)len);
		p += len;
	}

	len = p - buf.data();
	SendToClient(Client, 760, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}


void NotifyTopListDesc(std::shared_ptr<ClientNode> Client)
{
	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;
	auto WriteTopListDescFixedText = [](BYTE*& out, const char* text)
		{
			memset(out, 0, MaxNickName);
			memcpy(out, text, MaxNickName);
			out += MaxNickName;
		};

	USHORT Count = TopListDescs.size();
	Write16(p, Count);
	for (USHORT i = 0; i < Count; i++)
	{ //Descs
		BYTE* pDescs = p;
		Write16(pDescs, 0); //len
		Write16(pDescs, TopListDescs[i].ID);

		WriteTopListDescFixedText(pDescs, TopListDescs[i].Name);
		WriteTopListDescFixedText(pDescs, TopListDescs[i].ValueDesc);
		WriteTopListDescFixedText(pDescs, TopListDescs[i].TitleName);

		Write8(pDescs, TopListDescs[i].HasOtherInfo); //HasOtherInfo
		if (TopListDescs[i].HasOtherInfo)
		{ //Other
			BYTE* pOther = pDescs;
			Write16(pOther, 0); //len

			WriteTopListDescFixedText(pOther, TopListDescs[i].IntParaDesc0);
			WriteTopListDescFixedText(pOther, TopListDescs[i].IntParaDesc1);
			WriteTopListDescFixedText(pOther, TopListDescs[i].StrParaDesc0);
			WriteTopListDescFixedText(pOther, TopListDescs[i].StrParaDesc1);

			len = pOther - pDescs;
			Set16(pDescs, (WORD)len);
			pDescs += len;
		}

		Write8(pDescs, TopListDescs[i].IsEnableSelfRank);
		Write8(pDescs, TopListDescs[i].TabGroup);
		len = pDescs - p;
		Set16(p, (WORD)len);
		p += len;
	}
	len = p - buf.data();
	SendToClient(Client, 701, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}

static bool IsOfficialTopListExtRecord(USHORT ID)
{
	for (const auto& Desc : TopListDescs)
	{
		if ((USHORT)Desc.ID == ID)
			return Desc.HasOtherInfo != 0;
	}

	// 兜底：配置未加载或缺少 ID 时，按本次官包抓包中已确认的扩展记录 ID 保底。
	switch (ID)
	{
	case 0x004A: // 74 赛季战勋
	case 0x0049: // 73 战勋红人
	case 0x00CA: // 202 连胜之星全服排行
	case 0x005F: // 95 拉力赛总荣誉
	case 0x004C: // 76 赛季荣誉
	case 0x004B: // 75 车队总荣誉
	case 0x005A: // 90 宝宝红人
	case 0x007E: // 126 情侣二宝红人
	case 0x006C: // 108 多宠天梯积分
		return true;
	default:
		return false;
	}
}

static UCHAR GetOfficialTopListAreaId(USHORT ID)
{
	// 官包 pcaps/12/魅力达人/打开红人榜.pcapng:
	// 0x0082 排位短记录尾部为全 0；其余红人榜短/扩展记录 AreaId 为 1。
	return ID == 0x0082 ? 0 : 1;
}

static void WriteOfficialTopListFixedName(BYTE*& p, const std::string& NickName)
{
	memset(p, 0, MaxNickName);
	if (!NickName.empty())
	{
		const size_t copyLen = std::min<size_t>(NickName.size(), MaxNickName);
		memcpy(p, NickName.data(), copyLen);
	}
	p += MaxNickName;
}

static void WriteOfficialTopListShortTail(BYTE*& p, USHORT ID)
{
	Write8(p, 0); // HasOtherInfo
	Write8(p, GetOfficialTopListAreaId(ID)); // AreaId
	Write8(p, 0); // ParaNum
	Write32(p, 0); // Para placeholder
	Write32(p, 0); // reserved
	Write8(p, 0); // AnchorNum
}

static void WriteOfficialTopListExtTail(BYTE*& p, USHORT ID)
{
	Write8(p, 1); // HasOtherInfo
	{
		BYTE* pOtherLen = p;
		Write16(p, 0); // OtherInfo len: 官包为 0x31
		Write32(p, ID == 0x00CA ? 3 : 0); // IntPara0，0x00CA 官包样本为 3
		Write32(p, 0); // IntPara1
		memset(p, 0, MaxNickName); // StrPara0
		p += MaxNickName;
		memset(p, 0, MaxNickName); // StrPara1
		p += MaxNickName;
		Write32(p, 0); // IntPara2
		Write8(p, 0); // HasMapInfo
		Set16(pOtherLen, (WORD)(p - pOtherLen));
	}
	Write8(p, GetOfficialTopListAreaId(ID)); // AreaId
	Write8(p, 0); // ParaNum
	Write32(p, 0); // Para placeholder
	Write32(p, 0); // reserved
	Write8(p, 0); // AnchorNum
}

static void WriteOfficialTopListRecord(BYTE*& p, USHORT ID, UINT Uin, const std::string& NickName, UINT Value)
{
	BYTE* pPlayer = p;
	Write16(pPlayer, 0); // len
	Write32(pPlayer, Uin);
	WriteOfficialTopListFixedName(pPlayer, NickName);
	Write32(pPlayer, Value);

	if (IsOfficialTopListExtRecord(ID))
		WriteOfficialTopListExtTail(pPlayer, ID); // record len 0x58 / 88
	else
		WriteOfficialTopListShortTail(pPlayer, ID); // record len 0x27 / 39

	Set16(p, (WORD)(pPlayer - p));
	p = pPlayer;
}

