std::shared_ptr<ClientNode> GetRankedPVPTransport(
	const std::shared_ptr<ClientNode>& SessionClient,
	const std::shared_ptr<RoomNode>& Room)
{
	if (!SessionClient || !Room)
		return nullptr;

	std::lock_guard<std::mutex> lock(SessionClient->RankedPVPTransportMutex);
	std::shared_ptr<ClientNode> transport = SessionClient->RankedPVPTransport.lock();
	if (!transport || transport == SessionClient ||
		SessionClient->RankedPVPTransportRoomID != Room->ID ||
		SessionClient->RankedPVPTransportKey != Room->RaceSeed ||
		transport->Uin != SessionClient->Uin ||
		transport->TransportConnIDUin != SessionClient->Uin ||
		transport->TransportConnID == 0 || !IsValidWireConnID16(transport->ConnID) ||
		transport->ProtocolVersion == 0 || !transport->IsLogin || transport->deleteflag ||
		transport->ServerID != Room->ServerID)
	{
		return nullptr;
	}
	return transport;
}

bool ResolveActiveRaceStateClient(
	const std::shared_ptr<ClientNode>& PacketClient,
	UINT PacketUin,
	std::shared_ptr<ClientNode>& StateClient,
	std::shared_ptr<RoomNode>& Room)
{
	StateClient.reset();
	Room.reset();
	if (!PacketClient || PacketUin == 0 || PacketClient->Uin != PacketUin)
		return false;

	Room = GetActiveRaceRoom(PacketClient);
	if (Room)
	{
		StateClient = PacketClient;
		return true;
	}

	const std::shared_ptr<ClientNode> sessionClient = GetClient(PacketUin);
	const std::shared_ptr<RoomNode> rankedRoom = GetActiveRaceRoom(sessionClient);
	if (!sessionClient || sessionClient == PacketClient || !rankedRoom ||
		sessionClient->TaskID != 0xFFFC || rankedRoom->matchQueueType != 0x0A ||
		GetRankedPVPTransport(sessionClient, rankedRoom) != PacketClient)
	{
		return false;
	}

	StateClient = sessionClient;
	Room = rankedRoom;
	return true;
}

void ResetRankedPVPTransport(const std::shared_ptr<ClientNode>& SessionClient)
{
	if (!SessionClient)
		return;
	std::lock_guard<std::mutex> lock(SessionClient->RankedPVPTransportMutex);
	SessionClient->RankedPVPTransport.reset();
	SessionClient->RankedPVPTransportRoomID = 0;
	SessionClient->RankedPVPTransportKey = 0;
}

bool ResponsePVPLogin(std::shared_ptr<ClientNode> Client)
{
	if (!Client || Client->Uin == 0 || Client->TransportConnID == 0 ||
		!IsValidWireConnID16(Client->ConnID) || Client->ProtocolVersion == 0 || Client->deleteflag)
	{
		return false;
	}

	BYTE buf[2];
	BYTE* p = buf;
	Write16(p, 0); // ResultID
	const BOOL sent = SendToClientWithRawWireRouteIDsAndDialog(
		Client, 697, buf, static_cast<DWORD>(p - buf),
		-1, 101, static_cast<short>(Client->ConnID), -1, -1, Response);
	QQS_DebugPrintf10001(
		"[RANKED-PVP][697] Uin=%u TransportConnID=%u PVPConnID=%u RouteID=%u Sent=%d\n",
		Client->Uin, Client->TransportConnID, static_cast<unsigned>(Client->ConnID),
		static_cast<unsigned>(Client->ServerID), sent ? 1 : 0);
	return sent != FALSE;
}

void RequestPVPLogin(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (CrossServerTestHandlePVPLogin(Client, Body, BodyLen))
		return;
	constexpr size_t kWireBodyLen = sizeof(USHORT) + sizeof(UINT) * 3;
	if (!Client || !Body || BodyLen != kWireBodyLen ||
		Client->TransportConnID == 0 || !IsValidWireConnID16(Client->ConnID) ||
		Client->ProtocolVersion == 0 || Client->deleteflag)
	{
		return;
	}

	BYTE* p = Body;
	const UINT requestUin = Read32(p);
	const UINT requestTime = Read32(p);
	const UINT requestPVPKey = Read32(p);
	const std::shared_ptr<ClientNode> sessionClient = GetClient(requestUin);
	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(sessionClient);
	if (!sessionClient || sessionClient == Client || !room ||
		Client->TransportConnIDUin != requestUin ||
		(Client->Uin != 0 && Client->Uin != requestUin) ||
		!sessionClient->IsLogin || sessionClient->deleteflag ||
		GetClient(requestUin) != sessionClient ||
		sessionClient->TaskID != 0xFFFC || room->matchQueueType != 0x0A ||
		room->RankedStartPhase != RankedMatchStartPhase::AwaitEnterRoom ||
		!room->RaceAuthorityValid || room->RaceSeed == 0 ||
		requestPVPKey != room->RaceSeed || room->ServerID < 110 || room->ServerID > 113 ||
		Client->ServerID != room->ServerID)
	{
		QQS_DebugPrintf10001(
			"[RANKED-PVP][697-REJECT] ReqUin=%u Time=%u Key=%u TransportConnID=%u RouteID=%u RoomID=%u Phase=%u\n",
			requestUin, requestTime, requestPVPKey,
			Client ? Client->TransportConnID : 0,
			Client ? static_cast<unsigned>(Client->ServerID) : 0,
			room ? room->ID : 0,
			room ? static_cast<unsigned>(room->RankedStartPhase) : 0);
		return;
	}

	Client->Uin = requestUin;
	Client->IsLogin = TRUE;
	{
		std::lock_guard<std::mutex> lock(sessionClient->RankedPVPTransportMutex);
		sessionClient->RankedPVPTransport = Client;
		sessionClient->RankedPVPTransportRoomID = room->ID;
		sessionClient->RankedPVPTransportKey = room->RaceSeed;
	}
	if (!ResponsePVPLogin(Client))
	{
		ResetRankedPVPTransport(sessionClient);
	}
}

void RequestPVPHello(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (CrossServerTestHandlePVPHello(Client, Body, BodyLen))
		return;
	(void)Body;
	if (!Client || BodyLen != sizeof(USHORT) || Client->TransportConnIDUin == 0)
		return;

	const std::shared_ptr<ClientNode> sessionClient = GetClient(Client->TransportConnIDUin);
	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(sessionClient);
	const std::shared_ptr<ClientNode> pvpClient = GetRankedPVPTransport(sessionClient, room);
	if (!sessionClient || !room || !pvpClient ||
		(Client != sessionClient && Client != pvpClient) ||
		room->matchQueueType != 0x0A || sessionClient->TaskID != 0xFFFC ||
		room->RankedStartPhase < RankedMatchStartPhase::BanMapResult ||
		room->RankedStartPhase == RankedMatchStartPhase::Failed)
	{
		return;
	}

	BYTE result[2];
	BYTE* p = result;
	Write16(p, 0); // ResultID
	SendToClientWithRawWireRouteIDsAndDialog(
		pvpClient, 703, result, static_cast<DWORD>(p - result),
		-1, 101, static_cast<short>(pvpClient->ConnID), -1, -1, Response);
}



void ResponseChangeIdentity(std::shared_ptr<ClientNode> Client, char SetOrUnset, char IsExRightFlag, UINT IdentityFlag)
{
	if (!Client)
		return;

	if (IsExRightFlag != 0 && IdentityFlag < QQS_EX_RIGHT_FLAG_BYTES * 8u)
	{
		const UINT byteIndex = IdentityFlag >> 3;
		const BYTE bitMask = static_cast<BYTE>(1u << (IdentityFlag & 7u));
		if (SetOrUnset != 0)
			Client->ExRightFlags[byteIndex] |= bitMask;
		else
			Client->ExRightFlags[byteIndex] &= static_cast<BYTE>(~bitMask);

		Client->XiaoPendFlag = (Client->ExRightFlags[15] & 0x01) != 0;
		Client->CheDengFlag = (Client->ExRightFlags[16] & 0x08) != 0;
		PlayerDB_UpdateExRightFlagHex(Client->Uin, Client->ExRightFlags, QQS_EX_RIGHT_FLAG_BYTES);
	}

	BYTE buf[2 + 1 + 1 + 4 + 4 + QQS_EX_RIGHT_FLAG_BYTES] = { 0 };
	BYTE* p = buf;
	Write16(p, 0); // ResultID
	Write8(p, SetOrUnset);
	Write8(p, IsExRightFlag);
	Write32(p, IdentityFlag);
	Write32(p, Client->PlayerIdentity);
	memcpy(p, Client->ExRightFlags, QQS_EX_RIGHT_FLAG_BYTES);
	p += QQS_EX_RIGHT_FLAG_BYTES;

	SendToClient(Client, 131, buf, static_cast<size_t>(p - buf), Client->ConnID, FE_PLAYER, 1, Response);
}

void RequestChangeIdentity(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	// 21543 CRequestChangeIdentityPara:
	// MSGHEAD::BodyLen(2) + Uin(4) + Time(4) + SetOrUnset(1) +
	// IsExRightFlag(1) + IdentityFlag(4) + BeginBit(4) + EndBit(4) +
	// ExRightFlag[24] = 48.
	constexpr size_t kRequestBodyLen =
		sizeof(USHORT) + 4 + 4 + 1 + 1 + 4 + 4 + 4 + QQS_EX_RIGHT_FLAG_BYTES;
	if (!Client || !Body || BodyLen != kRequestBodyLen) {
		return;
	}

	BYTE* p = Body;
	Read32(p); // Uin
	Read32(p); // Time
	char SetOrUnset = Read8(p);
	char IsExRightFlag = Read8(p);
	UINT IdentityFlag = Read32(p);
	Read32(p); // BeginBit (SetOrUnset == 2 bulk request; not used by the single-bit path)
	Read32(p); // EndBit
	p += QQS_EX_RIGHT_FLAG_BYTES; // ExRightFlag[24]

	ResponseChangeIdentity(Client, SetOrUnset, IsExRightFlag, IdentityFlag);
}
